INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanjijukugo Flash', 'Sanjijukugo Flash is a free mini Flash game provided by GAMEDESIGN. It''s very simular to Yojijukugo Flash. "Sanjijukugo" is a Japanese idiom consisting of 3 kanji. In each stage, some kanji are randomly placed. The goal is to construct Sanjijukugo by rearranging them with a mouse in all 5 stages.' FROM games WHERE igdb_id = 141348 ON CONFLICT (game_id, language_code) DO NOTHING;
