INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series vol. 79: Akko ni Omakase! The Party Quiz', 'The Party Quiz: Akko ni Omakase: This entry in D3''s Simple series of budget titles is set up like a television quiz show, with over 1000 questions included. In addition to a couple of single player quiz modes, the game lets up to eight players get together for multiplayer play using the multitap. The game includes four unique types of quizzes.' FROM games WHERE igdb_id = 203320 ON CONFLICT (game_id, language_code) DO NOTHING;
