INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indigo Prophecy', 'Indigo Prophecy is an action-adventure game that involves the player in making decisions to alter the narrative. The name change in North America was made to avoid confusion with Michael Moore''s Fahrenheit 9/11 documentary film, which was released in 2004. Indigo Prophecy introduced elements like ethical ambiguity, romance, the inability to perish, and interactive storytelling that would endure in Quantic Dream later games.' FROM games WHERE igdb_id = 1928 ON CONFLICT (game_id, language_code) DO NOTHING;
