INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Field Mobile II', 'King''s Field II is an action RPG where the players explore not only dark labyrinths but also fields, sea shores, ice caves, huge beetles'' nests, battle arenas, temples, etc. Magic spells expand the tactics. Useful functions like lock-on and auto-mapping make the gameplay more comfortable. King''s Field Mobile II is the third and final King''s Field game for mobile phones.' FROM games WHERE igdb_id = 340965 ON CONFLICT (game_id, language_code) DO NOTHING;
