INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jade Empire', 'Set in an ancient world inspired by mythical China, Jade Empire lets you train under your master''s watchful eye as you learn powerful martial arts and mystical powers. When danger threatens, you''ll travel across the world, from the harsh mountains of the Land of Howling Spirits to the lush gardens of the Imperial City. In your adventures, you must face powerful human and supernatural foes, learn the exotic and magical martial arts, and discover the darkest secrets of the world. Practice the greatest fighting styles and defeat the most powerful enemies to become a master of martial arts.' FROM games WHERE igdb_id = 5867 ON CONFLICT (game_id, language_code) DO NOTHING;
