INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starshine Legacy Episode 2: Secret of Pine Hill Mansion', 'You play as Linda, a show jumper. Linda is torn between school and show jumping and finds out one day that she has supernatural abilities. She can talk to her horse Meteor and learns of an old secret. Discover the truth together with Linda and her friends.' FROM games WHERE igdb_id = 196737 ON CONFLICT (game_id, language_code) DO NOTHING;
