INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empire-earth-ii', 1608, '2005-04-26', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22ul.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uaehtx69mb3ugwatp9zj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire Earth II', 'Relive the complete span of human history! Lead the great nations of Korea, Germany and America in the base game and Egypt, Russia and the Masai in the add-on. Take part in the greatest battles in history of mankind. From quests for independence or rises to power, to the Civil and Wold War, Empire Earth 2 will show you all the faces of ancient and modern warfare. Choose your path from clear military dominance to a complicated diplomatic approach and look at the world from the perspective of famous leaders. We are inviting you to a great journey into the history of great nations with the best instalment of this famous series. Along with small episodes of sci-fi, when the creators wanted to predict what will come in the future, it is one of the best RTS and historical game ever created. Besides this is the only way to check out what would have happened when one tank would attack XV century Heavy Cavalry!' FROM games WHERE igdb_id = 1608 ON CONFLICT (game_id, language_code) DO NOTHING;
