INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spikeout-battle-street', 6056, '2005-03-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4to4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spikeout: Battle Street', 'Based on the 3D coin-on arcade title of the same name, SpikeOut: Battle Street offers a quick single-player mode that''s about two to four hours long and each time it''s beaten, a new character, with slightly different special attacks, opens up. There are around 10 levels, and 12 unlockable characters, and an online mode. You can connect with three other players for a four-player online bout on Xbox Live, and as a "sort-of" team, you then proceed to smack infinite nameless thugs into polygonal paste. The game works one way: Four humans against the computer AI. You''ve got a punch, kick, jump, and grapple move, and when pressed multiple times, each button ignites combos. By grappling an enemy from various angles and by pressing the Dpad in different directions when executing the throw renders various satisfying hurls.' FROM games WHERE igdb_id = 6056 ON CONFLICT (game_id, language_code) DO NOTHING;
