INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys IV: Mask of the Sun - A New Theory', 'Ys IV: Mask of the Sun - A New Theory is a remake of the original Ys IV for the Super Famicom. It follows the story of the original, but revamps the combat to be based on a more traditional button-press system than the original game''s "bump" combat, based on running into enemies off-center.' FROM games WHERE igdb_id = 65102 ON CONFLICT (game_id, language_code) DO NOTHING;
