INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blades-of-thunder', 49309, '2005-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nihglpdqem70ett42rki.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blades of Thunder', 'A U.S. recon team reports a terrorist cell is planning a major attack in the Middle East, hoping to overrun the oil refineries of the Gulf States to fuel worldwide terror. To secure our freedom you must hunt down and destroy this threat before it strikes. Take command of a deadly gunship to deal America''s wraith in the steel jacketed fury of today''s deadliest weapon systems. The game features 10 operation levels with air, land and sea missions, topped by elaborate boss fights. Your gunship''s tactical weapon systems include machine guns, hydra rockets and homing missiles. There are also weapon and armor power-ups found throughout the game. Use radar to keep on top of targets and enjoye the real-time 3D graphics packed with realistic visual effects. Features multiple difficulty levels.' FROM games WHERE igdb_id = 49309 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49309 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
