INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ururun Quest: Koiyuuki', 'Ururun Quest - Koiyuuki is a fully voiced Japanese PS2 videogame classified as an ''Onna no Ko Senyou (Girl-targeted) Love Simulation+RPG'' by its developer. It was released in 2005 and marketed as the first ''RPG targeted towards girls''. The player acts as the main character, Ruri, while she adventures around her world with her friends and finding new companions.' FROM games WHERE igdb_id = 203392 ON CONFLICT (game_id, language_code) DO NOTHING;
