INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tricycle Racers', 'Tricycle Racers is a one or two player, keyboard or joystick controlled 3D arcade racing game developed by Jeppe Nielsen and published by Idigicon Limited. There are two modes of play, a single race or a championship, nine courses of varying complexity - most with power-ups, and a track editor so the player can create and race their own courses.' FROM games WHERE igdb_id = 388146 ON CONFLICT (game_id, language_code) DO NOTHING;
