INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pac-pix', 18275, '2005-03-10', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3bh4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dmvsp0lfl9p4740tvo7f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Pix', 'A mischievous magician, known for playing pranks on poor unsuspecting folks, created something known as "Ghost Ink," a fluid that pretty much turns any drawing into evil and vicious ghost monsters. Any ghost created with the ink ends up just as mischievous as the magician. Ink ghosts have invaded books and paintings, causing trouble within those realms, and now it''s up to Pac-Man to wipe out the ghost problem by using the "Ghost Pen," a device that allows him to enter the infested books and paintings to clear out the bad guys. Pac-Pix is a game tailored specifically for the Nintendo DS'' system capabilities. By drawing Pac-Man characters in a specific fashion (the mouth first, then the circle, all in one swoop), the drawing will come to life and munch anything in his path. Players can maneuver Pac-Man drawings in different directions by plotting pathways on the screen for the scribble to follow.' FROM games WHERE igdb_id = 18275 ON CONFLICT (game_id, language_code) DO NOTHING;
