INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combat Wings', 'It’s the 4th of June, 1942, and Japanese bombs are raining down on Midway – and you. This lethal assault is a prelude to an invasion whose success gives the enemy control over the Pacific. You are one of the American airmen who hold the outcome of this decisive battle in their hands.' FROM games WHERE igdb_id = 138170 ON CONFLICT (game_id, language_code) DO NOTHING;
