INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Zero 4', 'Mega Man Zero 4 is a video game created by Capcom and Inti Creates for the Game Boy Advance in 2005. It''s the fourth and final installment in the Mega Man Zero series, making Zero the first Mega Man subseries to see a proper conclusion. The game introduces the Zero Knuckle, a weapon that lets Zero steal other enemies'' weapons and use them for himself, as well as a new mechanic where Zero can alter weather conditions before entering one of the eight main levels.' FROM games WHERE igdb_id = 1778 ON CONFLICT (game_id, language_code) DO NOTHING;
