INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultraman Fighting Evolution Rebirth', 'Ultraman Fighting Evolution Rebirth is the 4th game in the Ultraman Fighting Evolution series. This game was released in the PlayStation 2 console. Its Story Mode involves Alien Mephilas launching a massive invasion using EX monsters (more powerful versions of the originals) and sending three ''Chaosroids'' (dark versions of Ultraman, Ultraseven, and Ultraman Taro) to the Land of Light. Eventually, Mephiles fuses with his final monster, Neo Chaos Darkness. With the combined effort between Cosmos and the other Ultras, they managed to defeat him and stop his invasion.' FROM games WHERE igdb_id = 72598 ON CONFLICT (game_id, language_code) DO NOTHING;
