INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Love Katamari', 'We Love Katamari, is a third-person puzzle-action video game where the player controls the Prince, the 5-centimeter-tall son of the god-like entity the King of All Cosmos, who rolls around a "katamari", a magical ball that causes objects smaller than it to attach to it. Throughout each level, the play must collect objects in order to fulfill objectives set by the prince''s father.' FROM games WHERE igdb_id = 6454 ON CONFLICT (game_id, language_code) DO NOTHING;
