INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the Abyss', 'This entry in Namco''s popular Tales series takes place in a world where prophecies clue people in to future happenings. Tales of the Abyss boasts a revolutionary new free roaming battle system allowing players to move anywhere on the battlefield, a first in the Tales series which brings new depth to the intense, high-action battles that Tales games are knows for.' FROM games WHERE igdb_id = 1207 ON CONFLICT (game_id, language_code) DO NOTHING;
