INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman: Hoodlums'' Revenge', 'Rayman: Hoodlums'' Revenge is an isometric platformer game based on Rayman 3: Hoodlum Havoc. A spin-off in the Rayman series, Hoodlum''s Revenge takes place directly after the events from Rayman 3: Hoodlum Havoc and for the first in the series, aside from multi-player games, Rayman''s friend Globox is featured as a playable character.' FROM games WHERE igdb_id = 1967 ON CONFLICT (game_id, language_code) DO NOTHING;
