INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ankh-reverse-the-curse', 4849, '2005-11-04', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6t3c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6e5s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ankh: Reverse the Curse', 'Ankh is a point-and-click 3D adventure game by Deck13 Interactive. It features a fully three-dimensional environment with cineastic camera movement. All content is fully spoken and the soundtrack reflects an authentic Egyptian atmosphere. Humor is an important aspect of the game, and the influence of classic LucasArts adventure games is noticeable. The player takes the role of Assil, the son of a respected architect in Cairo. Assil is a party animal but at some point one of his party-nights turned out sour. When he tries to have some fun in the pyramids with two friends of his, he accidentally breaks some urns and thus disturbs the mummy resting in the pyramid. The mummy punishes Assil by placing a death curse on him, and now he has 24 hours to remove the curse and save himself. Later in the game Assil meets the Arabian ambassador''s daughter Thara, who is also a playable character. Requires a game patch which consists of an updated audio .dll file made for Vista to run on Windows Vista or Windows 7.' FROM games WHERE igdb_id = 4849 ON CONFLICT (game_id, language_code) DO NOTHING;
