INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('makai-kingdom-chronicles-of-the-sacred-tome', 22540, '2005-03-17', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1owt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Makai Kingdom: Chronicles of the Sacred Tome', 'Makai Kingdom is the fourth Nippon Ichi-developed tactical RPG on PlayStation 2 and it follows closely in the footsteps of the previous games of the same style, which are Disgaea: Hour of Darkness, La Pucelle: Tactics and Phantom Brave. Lord Zetta, the king of Netherworld, tried to rewrite the history of the land but didn''t succeed, and in the process brought demise onto himself. Three evil Overlords appeared before Zetta and promised to help him in his quest to take over the land once more. The player takes control of Zetta and his army to return Netherworld to its rightful owner. The game mechanics consist of several stages in which the player must defeat the enemy or fulfill other tasks to advance to the next level. Fighting is done in turns, meaning that once the player has moved and attacked, it''s the enemy''s turn to move his troops one by one. When the battle is won, the next level becomes selectable. Between fights, you can improve your squad of fighters by buying better weapons, recruiting more soldiers and so on.' FROM games WHERE igdb_id = 22540 ON CONFLICT (game_id, language_code) DO NOTHING;
