INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('classic-action-devilish', 47890, '2005-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6gst.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Classic Action: Devilish', 'By combining a fast paced brick-and-paddle system along with great level design, we are bringing the fun and excitement in the vein of Breakout to a whole another level. This retro title has been enhanced with the better graphics, gameplay and the ability to use both screens. If you''re a fan of action pinball, this title is for you. Utilize the features of the DS to add a new element of fun and control to the game as you bounce your magical orb through the labyrinth both horizontally and vertically. Use the shoulder buttons to rotate your paddles to shoot your orb in any direction. Find and utilize various power-ups throughout your journey to aid you in your fight against evil. There is a total of 5 levels (with several sub-levels within each) with new and unique challenges and varying environments. Each level has a unique end boss that must be defeated to continue. The game automatically saves your progress so you can come back and play (replay) a level at anytime.' FROM games WHERE igdb_id = 47890 ON CONFLICT (game_id, language_code) DO NOTHING;
