INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhem 2: The Cave', 'RHEM 2 is an adventure game from Knut Müller and Got Game Entertainment and the sequel to RHEM. It is distributed as a Macromedia Director file. Like Myst and Riven, Rhem 2 is a node-based first-person adventure game. The player explores a series of caverns in search of a certain artifact. The puzzles involve spatial reasoning, operating machinery, and logic.' FROM games WHERE igdb_id = 69248 ON CONFLICT (game_id, language_code) DO NOTHING;
