INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 4: GameStop Special Edition', 'A limited edition package released to mark the launch of Resident Evil 4, this set includes the game, a 20-page art book titled Resident Evil 4 Prologue, a numbered laser cel art print of Leon Kennedy, and a metal collector’s tin case. The Resident Evil 4 Collector’s Tin was a retailer-exclusive item available only through GameStop. It was not an official Capcom release. Some early editions also included a soundtrack CD.' FROM games WHERE igdb_id = 9668 ON CONFLICT (game_id, language_code) DO NOTHING;
