INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 4: Collector''s Edition', 'An exclusive Collector''s Edition of Resident Evil 4 released only in Australia, this package includes the base game and a bonus disc featuring videos from every title in the series—Resident Evil 0, Resident Evil, Resident Evil 2, Resident Evil 3: Nemesis, Resident Evil Code: Veronica, and Resident Evil 4—along with exclusive behind-the-scenes interviews and making-of content with the creators of Resident Evil 4.' FROM games WHERE igdb_id = 24211 ON CONFLICT (game_id, language_code) DO NOTHING;
