INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro 4', 'Spyro the Dragon #4 is a LCD game created for distribution at McDonalds''s restaurants. They were offered as a part of Happy Meals for limited time in 2005 to promote Crash Purple and Spyro Orange. The fourth handheld game was a dungeon crawler experience, where Spyro has to find all the gems while avoiding enemies in a limited period of time.' FROM games WHERE igdb_id = 336310 ON CONFLICT (game_id, language_code) DO NOTHING;
