INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Star Wars: The Video Game', 'LEGO Star Wars blends the unique world of LEGO with the adventure of Star Wars, for unforgettable action and fun. Live the most popular moments from The Phantom Menace, Attack of the Clones and Revenge of the Sith. Episodes I to III come to life -- and you can become a part of the story! Will you succumb to the dark side of the force or will you become a strong Jedi knight? Find your destiny.' FROM games WHERE igdb_id = 2681 ON CONFLICT (game_id, language_code) DO NOTHING;
