INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viewtiful Joe: Double Trouble!', 'You can play a movie action hero turned real action hero in Viewtiful Joe: Double Trouble. Viewtiful Joe: Double Trouble is a cel-shaded, side-scrolling action game that combines both puzzle-solving and platformer gameplay. Viewtiful Joe: Double Trouble makes use of both screens and the touch capabilities of the Nintendo DS to help you solve puzzles and progress through the game. Joe''s sister, Jasmine, also makes her first appearance in the series to help him out.' FROM games WHERE igdb_id = 5987 ON CONFLICT (game_id, language_code) DO NOTHING;
