INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Pirates'' Carnival', 'One Piece: Pirates’ Carnival brings the crazy pirate party without having to hit the ocean. Players can dominate the game board by defeating up to three friends in a series of zany games guaranteed to tickle the funny bone of the surliest of pirates. Gamers must evade bombs in a dodge ball field, locate the Pandaman, out-maneuver giant feet and more to become King of the Pirates.' FROM games WHERE igdb_id = 4054 ON CONFLICT (game_id, language_code) DO NOTHING;
