INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blitzkrieg 2', 'As its predecessor and the similar Sudden Strike games, Blitzkrieg 2 focuses on the battles of World War II rather than real-time strategy aspects like base building and resource extraction. The game features many new features and units over its predecessor; the graphics engine is upgraded, allowing for full 3D and the game features over 250 units compared to Blitzkrieg''s 200.' FROM games WHERE igdb_id = 7288 ON CONFLICT (game_id, language_code) DO NOTHING;
