INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ed, Edd n Eddy: The Mis-Edventures', 'Ed, Edd n Eddy: The Mis-Edventures is a 3D platform game based on the Cartoon Network animated television series Ed, Edd n Eddy. It was developed by Artificial Mind and Movement, Warner Bros. Interactive Entertainment and Cartoon Network Interactive, published by Midway Games and released on November 3, 2005, for the Nintendo GameCube, PlayStation 2, Xbox, Game Boy Advance, and PC. Midway announced the game on February 15, 2005.' FROM games WHERE igdb_id = 2722 ON CONFLICT (game_id, language_code) DO NOTHING;
