INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wild-arms-4', 1681, '2005-03-24', 56, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co61vm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dsqssny48d6qniyzfcwk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Arms 4', 'You play as a young teenager named Jude Maverick. You live in a quiet village that floats high above the ground, unaware of the world that lies beneath it. But one day, your world is shattered to pieces, and you descend onto the earth to face the terrible reality: the world of Filgaia was devastated by wars. A few settlements amidst rusty tanks is all that is left of civilization. The democratically elected government has some plans for improving the conditions of the world, but as you meet a young girl whom they used as a tool for their purpose, you realize you must find a better plan to save her, and the world, from complete destruction. The fourth installment of the Wild Arms series abandons its traditional Wild West theme and is set in a post-apocalyptic world. The gameplay system introduces hex-based battles. Battle screens are divided into seven hexes, each one of which can hold several party members or foes. You navigate your characters on the battle field, trying to force the enemy into an uncomfortable position. There is also a variety of skills you can learn and apply in battles to get benefits. As in previous Wild Arms games, the dungeons contain many environmental puzzles to solve.' FROM games WHERE igdb_id = 1681 ON CONFLICT (game_id, language_code) DO NOTHING;
