INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cafe Lindbergh: Summer Season', 'Cafe Lindbergh is a small restaurant famous for its tea, coffee, pastry, and sandwiches, and has become very popular by word-of-mouth for its atmosphere. The cafe is staffed by Itsuki, the master of the shop, Takumi, the cook, Tsukasa, a full-time waiter, and Shinya, a part-time waiter. A fifth employee Chihiro, is newly hired as another part-time waiter. Watching day-to-day events unfold through the eyes of these five co-workers, will they find themselves falling in love?' FROM games WHERE igdb_id = 269392 ON CONFLICT (game_id, language_code) DO NOTHING;
