INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-or-alive-4', 1392, '2005-12-29', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2szo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1dx4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead or Alive 4', 'Dead or Alive 4 is a fighting game and the fourth major title in the Dead or Alive video game series, its plot following the events of the 2001 title Dead or Alive 3. Dead or Alive 4 features 22 playable characters and many multi-tiered and interactive fighting arenas. DOA4 has a number of updates in reference to previous titles. Characters'' move lists have been vastly updated and four new characters have been added to the fighting roster, with returns from a couple of past characters as well. The counter system has been tightened, making the window for counters shorter and more difficult to execute, and the amount of damage that counters inflict has been changed.' FROM games WHERE igdb_id = 1392 ON CONFLICT (game_id, language_code) DO NOTHING;
