INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stuart Little 3: Big Photo Adventure', 'Following the destruction of George''s photography project in a freak flying accident, Stuart Little must save the day by scampering around New York City snapping everything in sight! Donning an exciting wardrobe, including golfing attire, a Native American costume, and a fireman''s uniform, Stuart will gain extra abilities required to complete his daring challenges. Along the way, players can explore the Big Apple in a range of miniature vehicles including a stunt bike, a helicopter, a speedboat, and a military tank.' FROM games WHERE igdb_id = 43455 ON CONFLICT (game_id, language_code) DO NOTHING;
