INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys: The Oath in Felghana', 'A complete 3D reimagining of the 16-bit console classic "Ys III: Wanderers From Ys," Ys: The Oath in Felghana is a fast-paced action role-playing game with tight controls, Metroidvania-style exploration elements, intense combat with epic screen-filling boss battles, and a thrashing, percussive arranged soundtrack that''s been heralded by many as one of the best of all time. Based on the original 2005 PC release, this classic is finally officially available in English with added Steamworks features such as achievements and cloud saving.' FROM games WHERE igdb_id = 15455 ON CONFLICT (game_id, language_code) DO NOTHING;
