INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conker: Live & Reloaded', 'Conker, gaming’s notoriously naughty squirrel, arrives on the Xbox with a bang in an all-new Xbox Live-enabled team-based shooter, Conker: Live and Reloaded. The game features intense Deathmatch and Campaign story line modes via Xbox Live and System Link, and players can compete as one of six combat specialists across multi-mission campaigns covering Old War and Future War. The warfare promises to deliver the non-stop action, humor, and innuendos Conker is famous for. Also included is the critically acclaimed single-player game, Conker’s Bad Fur Day, completely recreated for the Xbox with stunning graphics and unparalleled attitude.' FROM games WHERE igdb_id = 1425 ON CONFLICT (game_id, language_code) DO NOTHING;
