INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Legendia', 'Tales of Legendia is a fantasy role-playing game that continues the Tales series of games. You can play as Senel Coolidge, who encounters a giant, mysterious ship while adrift in a small boat with his sister. As you explore the history of the ship, you will encounter epic enemies and engage them using the "X-LiMBS" battle system, which lets you fight in real time like in a fighting game. The story is beset with unique characters designed by the animator featured in Kill Bill Vol. One.' FROM games WHERE igdb_id = 1206 ON CONFLICT (game_id, language_code) DO NOTHING;
