INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty: Roller Rescue', 'The lovable Sanrio character Hello Kitty has made her way onto the GameCube in a new adventure game. In Hello Kitty: Roller Rescue, you''ll explore Hello Kitty''s 3D world and encounter a variety of characters, villains, and puzzles. You''ll interact with more than 20 Sanrio characters that can help you battle enemies.' FROM games WHERE igdb_id = 3691 ON CONFLICT (game_id, language_code) DO NOTHING;
