INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('uefa-champions-league-2004-2005', 22303, '2005-02-03', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dzj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsu52.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UEFA Champions League 2004-2005', 'The Champions League, where the player leads one team to the Final in the Atatürk Olympic Stadium in Istanbul, in the quest to succeed FC Porto as European Champions, is one of the available modes, but not the most important. That honour goes to the "The Season" mode, where the player starts by creating his managing avatar, and then proceeds to a a series of 50 missions, with the first being a close last-week match against a Champions League spot rival, proceeding with a buyout of the club and increased expectations, and (hopefully) closing with the Champions League final. This mode also allows players to unlock additional features such as balls, a stadium and special exhibition modes by fulfilling objectives set by the club president during the season, some of them crucial matches (which can result in a sacking if failed), others simply a matter of balancing the squad. Other modes include the usual friendlies, "home and away" (a two-legged friendly), scenarios (where the player can create situations such as a defending a 1-0 nil for 45 minutes while two man down) and practice.' FROM games WHERE igdb_id = 22303 ON CONFLICT (game_id, language_code) DO NOTHING;
