INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arc-the-lad-end-of-darkness', 43649, '2005-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pwc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arc the Lad: End of Darkness', 'SCE takes the Arc the Lad series away from its roots and into an Online-playable action-adventure game. Players become a hunter who must travel the world and take on jobs, usually revolving around taking out enemies in real time using magic and special abilities. Collect cards from battle and events and equip them to gain new skills, all the while following an RPG-like storyline. You view the action from overhead, with a camera zooming in and out depending on the intensity of the action and occasionally switching to other angles for dramatic effect. You attack enemies in real time, tapping X once for a simple attack and repeatedly for a combo. You can also guard against attack, dash at an enemy, and press a button to run about the play field faster. The game places heavy emphasis on magic use, with the magic meter recovering automatically and quickly following each spell.' FROM games WHERE igdb_id = 43649 ON CONFLICT (game_id, language_code) DO NOTHING;
