INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 3: Dante''s Awakening', 'Devil May Cry 3: Dante''s Awakening is a prequel to the first Devil May Cry. The game plays very differently from its predecessors, as it puts much more emphasis on style rather than simple demon slaying. As such, combat is much more intense and faster than before. An all-new Style system that allows you to select your fighting style has also been incorporated.' FROM games WHERE igdb_id = 136 ON CONFLICT (game_id, language_code) DO NOTHING;
