INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WRC: FIA World Rally Championship', 'Immerse yourself in the first officially licensed handheld FIA World Rally Championship. WRC features 16 official rallies from around the world, including Japan and Mexico, plus 19 bonus stages and downloadable content. Now you can jump into the driver seat of one of 30 cars, including Evolution and Extreme spec cars. The game includes a total of six official car manufacturers and 17 official drivers from 2004. Test your skills against the best WRC drivers in the world, or link up to other PSPs via Wi-Fi for multiplayer battles.' FROM games WHERE igdb_id = 119183 ON CONFLICT (game_id, language_code) DO NOTHING;
