INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myth Makers: Trixie in Toyland', 'Join the Myth Makers in their latest adventure... Trixie in Toyland! The evil Penumbra, leader of the Acrostic Riders has stolen the Myth Makers Orbs and has hidden it from Toyland. Trixie must explore every inch of Toyland and find the stolen orbs and return balance to the Myth realm. But its not going to be easy! Along her way, Trixie must do battle with killer clows, rampaging robots, and hovering helecopters!' FROM games WHERE igdb_id = 5044 ON CONFLICT (game_id, language_code) DO NOTHING;
