INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek 2: The Adventure of Puss in Boots', 'Shrek 2: The Adventure of Puss in Boots is a 2005 Java ME action-platformer developed by Distinctive Developments and published by Eurofun, where players control Puss in Boots on a quest to steal the "Happily Ever After" potion and rescue other characters like Pinocchio and the Gingerbread Man from the Fairy Godmother''s clutches. The game is a mobile side-scroller with platforming and action elements, allowing players to experience an adventure through the Shrek universe on their Java-enabled phones.' FROM games WHERE igdb_id = 365950 ON CONFLICT (game_id, language_code) DO NOTHING;
