INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Prime Pinball', 'Samus Aran''s entry into the bumper-and-flipper world is a sleek, sci-fi classic gaming adventure that has her careening into gigantic boss monsters and bouncing through a variety of exciting pinball tables. Play tables across two screens at the same time using the touch screen to nudge the pinball table. Battle deadly enemies and experience a number of special modes such as Clone Machine Multiball and the Wall-Jump Challenge while you blast and bomb your high score into a state of pure pinball pandemonium.' FROM games WHERE igdb_id = 1109 ON CONFLICT (game_id, language_code) DO NOTHING;
