INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Gaiden Black', 'In Ninja Gaiden Black you can reprise the role of Ryu Hayabusa, ninja extraordinaire. This sequel to Ninja Gaiden supplies a new story and new missions, plus two more difficulty settings and cinematic cut scenes that provide background about the protagonist. Ninja Gaiden Black also incorporates the additional content from Hurricane Packs 1 and 2 and includes unlockable content such as the original arcade version of Ninja Gaiden.' FROM games WHERE igdb_id = 18735 ON CONFLICT (game_id, language_code) DO NOTHING;
