INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2K6', 'NHL 2K6 is a realistic hockey simulation in which you must take part in all aspects of running a franchise, from scheduling workouts to hitting a slap shot. The game includes revamped animations and more realistic player movement. NHL 2K6 also includes on-the-fly coaching that lets you make decisions during the game to affect your teams strategy and execution. You can even go online to challenge other gamers, track stats, or join a league.' FROM games WHERE igdb_id = 5965 ON CONFLICT (game_id, language_code) DO NOTHING;
