INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 76: The Hanasou Eigo no Tabi', 'The Hanasou Eigo no Tabi is an educational quiz game in which the player is a japanese tourist (there is the choice to be a boy or a girl at the beginning of the game) that travels to the United States for the first time. In the game the player is supposed to stay for a week in a certain town, in which he will have to communicate in English with the town people and that will deep the friendship while puzzled about cross-cultural questions and memories.' FROM games WHERE igdb_id = 203284 ON CONFLICT (game_id, language_code) DO NOTHING;
