INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grandia III', 'Grandia III is a role-playing video game developed by Game Arts and published by Square Enix for the PlayStation 2 console. Set in a fantasy world where technology has allowed man to fly in magic-powered aircraft, a boy named Yuki is determined to become a great pilot like his idol, the Sky Captain Schmidt. When he and his mother encounter a girl named Alfina who has the ability to communicate with the spiritual guardians of the world, they become involved in the plot to discover the secrets of the world''s past and face an evil rogue guardian named Xorn.' FROM games WHERE igdb_id = 18071 ON CONFLICT (game_id, language_code) DO NOTHING;
