INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starshine Legacy Episode 1: Mystery of the Soul Riders', 'Mystery of the Soulriders follows four girls as they combat evil forces in their town through the power of friendship; both with each other, and with their magical talking horses. The game opens with Lisa, on her first day of school, helping the horse Starshine ride again. But who is the old man Mr. Sands, and why does Starshine feel pain whenever he is near?' FROM games WHERE igdb_id = 196735 ON CONFLICT (game_id, language_code) DO NOTHING;
