INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat: Shaolin Monks', 'Mortal Kombat: Shaolin Monks is an action-adventure beat ''em up video game set in the Mortal Kombat universe. Players take on the roles of the iconic Shaolin monks Liu Kang and Kung Lao, either solo or in cooperative mode, as they defend Earthrealm against the threats of Outworld. The game offers a reimagining of the storyline from Mortal Kombat II.' FROM games WHERE igdb_id = 1614 ON CONFLICT (game_id, language_code) DO NOTHING;
