INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-ball-z-supersonic-warriors-2', 2577, '2005-11-20', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3w9t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/he7jy7bl82bkmbwflzgq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Supersonic Warriors 2', 'Supersonic Warriors 2 is the DS sequel to the GBA fighting game Dragon Ball Z: Supersonic Warriors, based on Akira Toriyama''s Dragon Ball series. The game features one-on-one battles between over 30 characters with their own movement and combos. There is a main path in the story mode that coincides with Toriyama''s story for every character and some other paths played out as "what if?" scenarios, adding replayability to the game. Next to the story mode, there is the Z battle, the VS battle, Maximum, Free battle and Practice mode. The game has three difficulty levels. In team battles the player can tap the touchscreen to select another fighter. Touch can also be used to perform a powerful combined attack when it is available. The sequel moves away from the level system of the first game, where reaching a new character level led to upgraded statistics, or new sprites and attacks. This is replaced by individual characters that become available when a sufficient amount of Dragon Points is available.' FROM games WHERE igdb_id = 2577 ON CONFLICT (game_id, language_code) DO NOTHING;
