INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lords-of-the-chaos', 263478, '2005-02-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6zq5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco4x9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of the Chaos', 'Lords of the Chaos is a single player real time strategy game which has everything needed for an unforgettable experience. The game has a default campaign with the story shown before each map starts and had a download option, with multiple server providers, to get additional campaigns or maps. Some downloads were free including a second campaign available at launch while others had to be bought separately. There are 4 unit types in the game with commands for movement or a general attack into the fog of war and a behavior option that is active when waiting for orders, the hero unit can also cast spells. There are 6 map tile types with grass as the only place to build, swamp and sand allow movement, water and mountains acting as barriers along with trees that can be chopped down for resources and to make paths. There are 6 buildings available with different uses and menu options: main camp to train workers and the hero, farms for food to manage army size, Training camps to train and upgrade warriors or catapults, Towers for vission or upgraded to hold a catapult, wizard tower to research or change a hero''s spells and gold mines for workers to gather money. Due to CPU speed and memory differences between phone models, some features were removed from the relevant versions. These changes can include the map download feature, animations and spells.' FROM games WHERE igdb_id = 263478 ON CONFLICT (game_id, language_code) DO NOTHING;
