INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Truck: Apocalypse', 'Hard Truck: Apocalypse (Ex Machina) is a vehicular combat post-apocalyptic science fiction video game developed by Russian game developer Targem Games. It is a Privateer-like game on vehicles instead of spaceships set in a post-apocalyptic Europe. The player controls an armored truck and roams between settlements trading with locals, completing quests and fighting numerous enemies to upgrade his truck and acquire better weapons to progress through the main storyline.' FROM games WHERE igdb_id = 23003 ON CONFLICT (game_id, language_code) DO NOTHING;
