INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Predator: Concrete Jungle', 'Predator: Concrete Jungle reveals never-shown parts of the Predator''s history on Earth. In this 3rd-person action adventure, you''ll cut between two different eras - 1930 and 2030. When a Mafia family decides to out the existence of Predators, the hunters realize their camouflage will be useless - so they endeavor to hunt the mobsters down and kill them. The game is named after the first volume of the Dark Horse Comics Predator comics series, but does not share the same plot.' FROM games WHERE igdb_id = 5986 ON CONFLICT (game_id, language_code) DO NOTHING;
