INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Curse of Darkness', 'Castlevania: Curse of Darkness is a direct sequel to Castlevania III: Dracula''s Curse. The game differs from its predecessor in a number of ways, including a more complex, action-adventure style of gameplay featuring character growth based on accumulated experience points. Master the unique new skills of Devil Forgery to develop and enhance Innocent Devils - allies that will help to conquer enemies, evade traps and solve challenging puzzles.' FROM games WHERE igdb_id = 1137 ON CONFLICT (game_id, language_code) DO NOTHING;
