INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-monkey-ball-deluxe', 2929, '2005-03-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rhe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uiod8c4l48fcseuydtpv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Monkey Ball Deluxe', 'This game is basically a fusion of Super Monkey Ball 1 and 2 for the PS2 and XBox. All of the levels from those two games are available in this collection, and all of the minigames are already unlocked and included. Formerly only available to GameCube players, the Super Monkey Ball series has made it to the PS2 and Xbox after a wait of almost 3 and a half years. The game itself plays very much like the old arcade game Marble Madness. You control a monkey in a ball, and you have to navigate it through many perilous labyrinths to the finish. In the previous two games you had limited lives/tries, but here you have infinite lives, which makes it all the easier.' FROM games WHERE igdb_id = 2929 ON CONFLICT (game_id, language_code) DO NOTHING;
