INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carious Weltling II', 'The main objective of control a weltling to make it stay alive in a boiling desert by collecting maggots and taking out enemies. The background information about weltlings is presented as a series of drawn stills and the graphics have received a large overhaul. There are new enemies, new attack patterns and a familiar selection of power-ups.' FROM games WHERE igdb_id = 111553 ON CONFLICT (game_id, language_code) DO NOTHING;
