INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! Unmasked', 'The player uses Scooby-Doo to take down enemies and collect clues for Velma. Scooby-Doo can change costumes which can give him different moves such as kung-fu and fly like a bat. Without using these costumes some levels may not be possible to finish. This is the third Scooby-Doo game to feature a laugh track. In the Nintendo DS game, there are a few minigames included to make use of its touchscreen.' FROM games WHERE igdb_id = 2854 ON CONFLICT (game_id, language_code) DO NOTHING;
