INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TimeSplitters: Future Perfect', 'TimeSplitters: Future Perfect is a first-person shooter video game developed by Free Radical Design and published by EA Games for the PlayStation 2, GameCube and Xbox video game consoles. It is the third game in the TimeSplitters series, after TimeSplitters 2, which was released in 2002 (itself the sequel to TimeSplitters released in 2000). The game features a single-player mode consisting of levels where the player assumes the role of Sergeant Cortez, a time-traveling marine from the 25th century.' FROM games WHERE igdb_id = 2144 ON CONFLICT (game_id, language_code) DO NOTHING;
