INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi Connection V2', 'The Tamagotchi Connection V2 is the second Tamagotchi Connection release that was released by Bandai in June 2005. It was the first international Tamagotchi to have a shop and Gotchi Points. There are 2 babies, 4 toddlers, 10 teenagers and 35 adults with a total of 51 characters. Many characters from the vintage Tamagotchi virtual pets, as well as the Tamagotchi Connection Version 1 and the Keitai Kaitsuu Tamagotchi Plus return for this version.' FROM games WHERE igdb_id = 229943 ON CONFLICT (game_id, language_code) DO NOTHING;
