INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Webkinz Classic', 'Webkinz Classic is a multi-award winning virtual world for everyone aged 6+. On Webkinz.com, players discover a whole world of fun, caring and learning, while they adopt and play with their pets, decorate rooms, play games, collect prizes, and chat with their friends! With over 1,000 pets to adopt, more than 15,000 items to collect, and over 100 games and activities, Webkinz World is a place kids of all ages will enjoy! Content is in English only' FROM games WHERE igdb_id = 137951 ON CONFLICT (game_id, language_code) DO NOTHING;
