INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oz World', 'Oz World was a virtual world social MMORPG with an emphasis on meeting others as well as dating. Players could build their own in-game homes, collaborate on fishing, get married, and participate in various social activities. There was also a personals component to the game. Oz World mostly focused on fishing and collaboration rather than quests and combat, but there were in-game events and tons of customization options for those who wanted a casual relaxing MMO space. The game also had an item shop for extras.' FROM games WHERE igdb_id = 186747 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 186747 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
