INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom RPG', 'Choose one of three different characters and get ready to battle through hordes of deadly monsters, including returning favorites such as the Pinky, Cacodemon, and Revenant, as well as new threats like the Sawcubus and Sentinel! Battle towering bosses such as the Cyberdemon, Spider Mastermind, or the Pinkinator! Interact with other survivors of the invasion to get information about your environment and solve puzzles, but beware…not all of them can be trusted!' FROM games WHERE igdb_id = 101029 ON CONFLICT (game_id, language_code) DO NOTHING;
