INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Life: Gang Wars', 'Crime Life: Gang Wars is a free roaming crime-based beat em up. Mixing action and strategy elements within a gritty, detailed storyline to explore modern-day urban gang culture, the player is cast as a small-time homie who must work their way through the ranks to become a gang leader. Urban culture and the Hip Hop lifestyle is the focus of Crime Life: Gang Wars.' FROM games WHERE igdb_id = 5791 ON CONFLICT (game_id, language_code) DO NOTHING;
