INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rockman-exe-6-dennoujuu-glaga', 352770, '2005-11-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coanuu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4fi8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman EXE 6: Dennoujuu Glaga', 'The original version of Mega Man Battle Network 6: Cybeast Gregar. It has Completing requests will increase your rank up to Master. It has some of its content (namely the jobs from the Request BBS) locked behind Modification Cards (later known as Patch Cards), whereas the international version, for the lack of the e-Reader feature, have these features unlocked by default. It was also compatible with Rockman EXE Battle Chip Stadium and the Beast Link Gate, unlike the later releases.' FROM games WHERE igdb_id = 352770 ON CONFLICT (game_id, language_code) DO NOTHING;
