INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WTF: Work Time Fun', 'Created specifically for the PSP system, WTF is a crazy collection of fun and addictive mini-games that drive the player to perform sometimes trivial, sometimes mind-bending, but always fun jobs in pursuit of the almighty dollar. The latest in a long line of unique Japanese games that have gained popularity in the United States, WTF delivers gamers compelling, bite-sized morsels of frenzied arcade-style action unlike anything ever seen on the PSP system.' FROM games WHERE igdb_id = 42853 ON CONFLICT (game_id, language_code) DO NOTHING;
