INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yoshitsune-ki', 263951, '2005-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co706m.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshitsune-ki', 'Yoshitsune-ki is a historical action game released by Banpresto on December 1, 2005 for the PS2 and was Developed by Dream Factory . The game is known for having Popular Manga artist Takeshi Obata in charge of character design. The game takes place in the late Heian period to the early Kamakura period when Minamoto no Yoshitsune was active . While controlling the main character Yoshitsune, he fights monsters and the Heike with his companions, and aims to destroy the Heike by making full use of various swordsmanship in places such as Heiankyo, Hiraizumi , and Dannoura .' FROM games WHERE igdb_id = 263951 ON CONFLICT (game_id, language_code) DO NOTHING;
