INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman EXE 6: Dennoujuu Falzer', 'The original version of Mega Man Battle Network 6: Cybeast Falzar. It has Completing requests will increase your rank up to Master. It has some of its content (namely the jobs from the Request BBS) locked behind Modification Cards (later known as Patch Cards), whereas the international version, for the lack of the e-Reader feature, have these features unlocked by default. It was also compatible with Rockman EXE Battle Chip Stadium and the Beast Link Gate, unlike the later releases.' FROM games WHERE igdb_id = 352771 ON CONFLICT (game_id, language_code) DO NOTHING;
