INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarTech: Senko no Ronde', 'WarTech: Senko no Ronde thrusts the player into a distant future where humanity has colonized countless new galaxies and Earth has become a planet mined for its natural resources. A violent war has erupted as nations struggle for world domination. Rounder Mechs fill the skies as the fate of the world is determined through aerial combat.' FROM games WHERE igdb_id = 7245 ON CONFLICT (game_id, language_code) DO NOTHING;
