INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Strikers', 'Super Mario Strikers is the first game in the Mario Strikers series, it features a version of soccer without referees and rules and has power-ups and special strikes which count as two goals. In comparison to actual soccer, the game features a smaller version of the soccer field and each team has only five members instead of the usual eleven-a-side rule. The match time can be manually set from 2 to 15 minutes but is defined as 5 minutes by default. If time runs out when scores are level, a Sudden Death follows the regular game time where next goal wins.' FROM games WHERE igdb_id = 2256 ON CONFLICT (game_id, language_code) DO NOTHING;
