INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magnetism', 'A physics puzzle game in which players must drop a metal ball into a cup. Red magnets will attract the ball, green magnets will repel it, while electromagnets can be turned on and off. There are 2 different game modes: one where the claw is controlled with your mouse while the other allows the ball to be controlled by the arrow keys.' FROM games WHERE igdb_id = 262129 ON CONFLICT (game_id, language_code) DO NOTHING;
