INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: A Tear of Vermillion', 'The fourth game in the Legend of Heroes series and the second in the Gagharv Trilogy. The PSP remake was renamed to simply "The Legend of Heroes: A Tear of Vermillion" and was the first entry in the storied franchise to be localized into English. The other 2 games in the trilogy were renamed because of this.' FROM games WHERE igdb_id = 10943 ON CONFLICT (game_id, language_code) DO NOTHING;
