INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Shiroi Kage no Shoujo', 'The 10th installment in the Tantei Jinguuji Saburo series, and the first portable entry. When Jinguuji attends his friend''s funeral, his friend''s mother asks him to investigate a missing person, while police inspector Kumano asks him to investigate the urban myth called "Yuu-chan".' FROM games WHERE igdb_id = 49852 ON CONFLICT (game_id, language_code) DO NOTHING;
