INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ciao Bella: la Bella Romanza', 'Guide Elena Battista through her busy life, trying to balance career, family, and romance. She has 13 weeks to win Elio''s heart, whilst also making decisions and solving catastrophes in the lives of her friends and family. Control Elena''s day-to-day schedule in this life management sim. Complete new objectives each level, visit locations on the map, raise stats with different actions, and interact with various characters.' FROM games WHERE igdb_id = 133957 ON CONFLICT (game_id, language_code) DO NOTHING;
