INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1-2-3 Bumblebee', '1-2-3 Bumblebee is a computer game designed to help toddlers learn how to use the mouse. The Bumblebee behaves just like a "grown up" mouse pointer: Moving the mouse makes the Bumblebee fly, and clicking on squares will make colorful shapes appear. The feedback is reinforced by multi-tone sounds and voice recordings. Once your child progresses through all three "pages", they are rewarded with a little song. The game runs in fullscreen mode and the keyboard is locked to prevent your child from accidentally leaving the program.' FROM games WHERE igdb_id = 329489 ON CONFLICT (game_id, language_code) DO NOTHING;
