INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Flight', 'Night Flight is a Pokémon e-Reader game for the Game Boy Advance. In order to play Night Flight, two Pokémon Skyridge e-Reader cards must be scanned. The required cards are: Zubat (#117) and Golbat (#60). In Night Flight the player controls a Zubat which must eat as much food as possible. If the player runs into a Koffing three times then the game is over. The Koffing are invisible unless the player uses Zubat''s supersonic sound waves.' FROM games WHERE igdb_id = 233026 ON CONFLICT (game_id, language_code) DO NOTHING;
