INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gun Warrior: The Rider From Nowhere', 'Gun Warrior is a 3D first-person shooter with an Old West setting. The player takes control of Cole Tilghman, once a feared gunman. When an unknown gunfighter kills his brother, he returns to take him out along with the henchmen. The game consists of different missions in locations such as a town or a train. There are animated cut-scenes between missions with voice acting and often killed enemies will trigger a cinematic death sequence.' FROM games WHERE igdb_id = 27537 ON CONFLICT (game_id, language_code) DO NOTHING;
