INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rub Rabbits!', 'Rub Rabbits is the sequel to XY/XX: Feel the Magic and features all-new gameplay mechanics, which range from holding the Nintendo DS sideways and upside down to multiple game modes. The game includes all-new music, art, and characters, as well as the ability to customize the look of the object of your affection. The game has six different multiplayer modes, which are compatible for playing with up to four players at a time.' FROM games WHERE igdb_id = 20488 ON CONFLICT (game_id, language_code) DO NOTHING;
