INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chibi-Robo!', 'Like most families, the Sandersons bicker about money and cleaning. Unlike most families, though, they also have robotic spiders, aliens, and talking toys to worry about. Enter Chibi-Robo, a tiny robot programmed to spread happiness. Join him on his quest to restore order to the Sanderson house and SAVE THE WORLD!' FROM games WHERE igdb_id = 3856 ON CONFLICT (game_id, language_code) DO NOTHING;
