INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomoyo After: It''s a Wonderful Life', 'Tomoyo After: It''s a Wonderful Life is a Japanese adult visual novel developed by Key. Key later released versions of Tomoyo After without the erotic content. The story follows the lives of Tomoya Okazaki, a young man who recently graduated from high school, and his close friend Tomoyo Sakagami as they start to see more of each other in a romantic relationship.' FROM games WHERE igdb_id = 7218 ON CONFLICT (game_id, language_code) DO NOTHING;
