INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Domination', 'Massive Assault: Phantom Renaissance is the sequel to highly acclaimed turn-based strategy game Massive Assault. Massive Assault: Phantom Renaissance features a renewed global conflict between the Free Nations Union and Phantom League in distant space colonies. The game is based on the Massive Assault’s original "Secret Allies" concept, acknowledged by the press and the players as innovative and easy to learn and hard to master one and in many respects rejuvenating turn-based genre.' FROM games WHERE igdb_id = 9380 ON CONFLICT (game_id, language_code) DO NOTHING;
