INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doctor Who: SuDocWho', 'Each Doctor can only appear one time in each row, column and 3x3 square. The Doctor Who SuDocWho game is a Sudoku game with nine Doctors. The same rules apply as in a normal Sudoku game. Instead of nine numbers nine Doctors can be added. Completing the puzzle reveals the next doctor.' FROM games WHERE igdb_id = 237837 ON CONFLICT (game_id, language_code) DO NOTHING;
