INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWII: Tank Commander', 'It''s World War II, and from France to Germany, prepare to destroy the opposition and help free Europe from Nazi rule as you take command of a Sherman tank in General Patton’s Fourth Armored Division, Patton''s best and most elite division. Cut off the enemy at the Brittany Peninsula, escort Allied convoys, and smash Nazi forces across the Moselle. Rescue hostages, relieve the besieged 101st Airborne at Bastogne, cross the Rhine, and drive German forces out of France.' FROM games WHERE igdb_id = 94446 ON CONFLICT (game_id, language_code) DO NOTHING;
