INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GNOP', 'One of the world''s simplest video game concepts comes to life once more in GNOP, a fully customisable game in the spirit of "Pong" for one or two players. Bounce the ball off your paddle just right to prevent your opponent from catching it, but be careful not to miss it when it comes flying back to you! Now you can enjoy the game in any way you like, because GNOP 2.0 is more customisable than ever. Use your own graphics, sounds and music and change everything from paddle speeds to the size of the playing field, then save your setup and share it with friends!' FROM games WHERE igdb_id = 334446 ON CONFLICT (game_id, language_code) DO NOTHING;
