INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: Tactics', 'Return to Middle-earth in this tactical RPG and decide the fate of The Third Age. Build a Fellowship of heroes or create a force of evil with hundreds of skill, weapon, and ability upgrades. Send your armies into battle across legendary locations from the film trilogy and J.R.R. Tolkien''s fiction. A simultaneous turn-based multiplayer system delivers a combat unrivaled by any Tactics game. The board is set, the pieces are in motion. Middle-earth awaits you.' FROM games WHERE igdb_id = 22458 ON CONFLICT (game_id, language_code) DO NOTHING;
