INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('charlie-and-the-chocolate-factory-dvd-games', 343343, '2005-08-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9snv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwrsn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie and The Chocolate Factory DVD Games', 'The DVD featured several interactive games and activities These included: "Oompa-Loompa Dance" Game: Follow along and create your own Oompa-Loompa dance moves using your remote. A rhythm-based game where timing and coordination earn you higher scores. "The Inventing Machine": A mix-and-match game where you combine ingredients to invent your own wacky candy. The machine gives you fun (and sometimes gross!) results based on your combinations. "The Bad Nut" Game: Help the squirrels sort good nuts from bad ones like in the movie scene with Veruca Salt. A reaction game testing speed and accuracy. "Search for the Golden Ticket": A treasure hunt-style game where you explore different chocolate bars to find the hidden golden ticket. These games were accessible from the “Special Features” or “Fun and Games” section of the DVD menu and were playable using the DVD remote control. Some versions also included DVD-ROM content with printable activities and desktop games when played on a computer.' FROM games WHERE igdb_id = 343343 ON CONFLICT (game_id, language_code) DO NOTHING;
