INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nobunaga''s Ambition: Iron Triangle', 'Nobunaga''s Ambition: Iron Triangle is another entry in KOEI''s long-running series of grand strategy games. As in the previous installments, the player assumes the role of a Japanese feudal lord during the famous Sengoku period (from the XV to the XVII century).' FROM games WHERE igdb_id = 21290 ON CONFLICT (game_id, language_code) DO NOTHING;
