INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Law & Order: Criminal Intent', 'The world of the hit television show Law & Order: Criminal Intent comes to life on the PC as players take on the role of Detective Robert Goren to investigate four all-new murder cases while taking the on the role of Detective Robert Goren. Actor Vincent D''Onofrio voices the character while you scrutinize the crime scenes, analyze evidence and interview witnesses and suspects. With beautifully rendered graphics and voices just like members of the show''s cast, this thrilling 3rd person mystery adventure game will have players feeling like they''ve stepped into an actual episode of Law & Order: Criminal Intent.' FROM games WHERE igdb_id = 69695 ON CONFLICT (game_id, language_code) DO NOTHING;
