INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Superstar Baseball', 'The superstars of the Mushroom Kingdom have gathered on the diamond to power up America''s game! Pick a captain, fill your team with your favorite characters from the Mario universe, then hit the field. Each captain has a special Star Skill for pitching and batting, so whether you''re hurling fireballs as Mario or blasting curving banana-ball dingers as DK, you''ve never played ball like this!' FROM games WHERE igdb_id = 3986 ON CONFLICT (game_id, language_code) DO NOTHING;
