INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paintcan Panic', 'Grab a can of paint and spruce up Camp Kidney before Edward and the Dung Beetles stop you. Let loose in Paintcan Panic. The goal of the game is to fill the ground with paints while the Pintos are trying to catch you.' FROM games WHERE igdb_id = 357352 ON CONFLICT (game_id, language_code) DO NOTHING;
