INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shin-megami-tensei-devil-summoner--1', 357453, '2005-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaxv2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scy6ip.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Devil Summoner', 'Shin Megami Tensei: Devil Summoner is a remaster of the original Sega Saturn game that introduces a new difficulty, rebalances combat mechanics, changes the interface to resemble that of Devil Summoner: Soul Hackers, and adds quality of life features such as the Demon Compendium. Abandoning the post-apocalyptic themes of the original series, the story takes place in modern Japan. The player character is an unnamed college student who is attacked by demons along with his girlfriend; they are saved by the timely appearance of a suave demon-hunter named Kyouji. Shortly thereafter, Kyouji is found dead under suspicious circumstances. The protagonist is then trapped inside of a warehouse and murdered by a deranged killer named Sid. Rather than stay dead, the player finds himself in the reanimated body of the slain Kyouji, and escapes from the morgue. With the help of Kyouji''s voice, which guides the player from inside his head, the main character joins up with Kyouji''s female partner Rei in order to save the life of his girlfriend, who is still in danger.' FROM games WHERE igdb_id = 357453 ON CONFLICT (game_id, language_code) DO NOTHING;
