INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('10000-bullets', 14727, '2005-02-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co490o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3al0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10,000 Bullets', '10,000 Bullets is an action/third-person shooter in which the gun-wielding player character battles numerous enemies and bosses in different environments. Styled similar to cinematography found in The Wachowskis'' The Matrix film franchise and gameplay mechanics in games such as Dead to Rights and Max Payne, the player is given an ability to slow down time and thus dodge multitudes of flying bullets and other obstacles. The first level, "enhancement", slows down all action, including the player character. The second level, "Blitz", slows down only the enemies, allowing the player to move around at normal speed. The third level, "frozen time", halts everything around the player, who again maintains normal speed. By pressing the shoulder buttons, the player can lock-onto and switch aim at the various enemies. Successfully dispatching several foes in a row earns the player bonus points, which can be used at the end of a stage to purchase upgrades like more health, as well as special attacks and acrobatic evasion skills that can be mapped to certain controller buttons. The game features four playable characters (Crow, Alice, Dragon, and Boris), each of which has their own unique set of abilities. Between the action sequences, the player must advance the plot through a graphic adventure-style interface, where certain characters must be spoken to in order to continue.' FROM games WHERE igdb_id = 14727 ON CONFLICT (game_id, language_code) DO NOTHING;
