INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rigs of Rods', 'Rigs of Rods is an open source vehicle simulator licensed under the GNU General Public License version 3. What makes Rigs of Rods different to most simulators is its unique soft-body physics: vehicles, machines, objects, etc. are simulated in real-time as flexible soft-body objects, giving the simulation an extremely accurate behavior which entirely depends on the physical construction of the vehicles or objects you create.' FROM games WHERE igdb_id = 50775 ON CONFLICT (game_id, language_code) DO NOTHING;
