INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi Connection: Corner Shop', 'Tamagotchi Connection: Corner Shop lets you assist your virtual pet in building a business. Ten different shops act as unique minigames in which you must control your Tamagotchi character and assist customers. Three different playable characters are available, all with different personalities. The game also features stylus support to let you take advantage of the touch-screen features of the DS. Also, the multiplayer mode lets players swap in-game items.' FROM games WHERE igdb_id = 20491 ON CONFLICT (game_id, language_code) DO NOTHING;
