INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Ultramix 3', 'Dance Dance Revolution Ultramix 3 allows players to compete online and go head-to-head with other DDR fans from around the globe, talk live to other DDR players as well as download new songs and other content. Ultramix 3 also features never-before-seen offline modes that cater to the casual, beginner and advanced dancers. ''Freestyle Mode'' lets newcomers to the series dance to any song without having to follow specific dance steps on the screen.' FROM games WHERE igdb_id = 5801 ON CONFLICT (game_id, language_code) DO NOTHING;
