INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Chaos Theory', 'You are Sam Fisher, the NSA''s most elite black-ops agent. To achieve your mission you will kill from close range, attack with your combat knife, shoot with the prototype Land Warrior rifle, and use radical suppression techniques such as the inverted neck break. Also take on cooperative multiplayer infiltration missions, where teamwork is the ultimate weapon.' FROM games WHERE igdb_id = 911 ON CONFLICT (game_id, language_code) DO NOTHING;
