INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Stanley''s House I', 'Dr. Stanley''s House was created by James Li and is a point-and-click adventure game. It has a mysterious plot with some twists and turns that is very creepy at times. The lush colored graphics provide a striking contrast to the moody atmospheric soundtrack, with several cut scenes that develop the story as you play.' FROM games WHERE igdb_id = 141091 ON CONFLICT (game_id, language_code) DO NOTHING;
