INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-raper-ii', 22418, '2005-04-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6sc1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Raper II', 'Battle Raper II is a weapon-based 3D fighting game in which the players are able to knock female opponents'' clothing off. Every character has unlimited guard, a move that can not be blocked, as well as a super move. The game also features a variety of alternative clothing items and weapons for all the characters that can be used to edit their models. The game includes a single-player story mode, a multiplayer mode, and an Extras mode which is unlocked after finishing the storyline. As opposed to the first Battle Raper, the sequel actually does not feature rape but only consensual sex. Once a fight against a female character is won, the game enters a special mode where the unconscious woman lies on the ground in front of the player who now has to heal her wounds. The Replay mode allows the player to have sex with a chosen female character.' FROM games WHERE igdb_id = 22418 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 22418 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
