INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shonen Jump''s One Piece', 'One Piece also referred to as Shonen Jump''s One Piece is a 2-D platforming adventure video game for the Nintendo Game Boy Advance based on the 4kids dub of the One Piece anime. Developed by Dimps and published by Bandai, it was released on September 7, 2005. It is the only One Piece game to be only released in the USA, and the first out of two to not see a release in Japan.' FROM games WHERE igdb_id = 75755 ON CONFLICT (game_id, language_code) DO NOTHING;
