INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Gaïa', 'Dino Gaïa was a free online text-based dinosaur breeding simulation game. Players could choose, raise, and train their dinosaur, ensuring its daily needs such as food, water, and hunting were met. While it featured some illustrations to enhance immersion, the core gameplay relied on written descriptions and interactive choices within quests. The game also offered community features, allowing players to interact and participate in various quests and competitions.' FROM games WHERE igdb_id = 326060 ON CONFLICT (game_id, language_code) DO NOTHING;
