INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures in Odyssey and the Treasure of the Incas', 'Unravel the mysterious accusations against Eugene Meltsner''s parents as you play the role of Whit, Connie and Eugene. Investigate clues and discover important facts, eventually leading you to the South American jungle to solve the mystery. It also teaches and encourages family values by rewarding Christian virtues like faith, trust and more. Enjoy hours of interactive game play! Compatible with PC and Mac.' FROM games WHERE igdb_id = 80366 ON CONFLICT (game_id, language_code) DO NOTHING;
