INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Street V3', 'The GameCube version features Mario, Luigi, and Princess Peach as playable characters, collectively known in-game as the "Nintendo All-Stars". This is in response to a deal between EA and Nintendo in which EA would include Nintendo characters and properties in a few of their games; another game to take advantage of this was SSX Tour. A basketball court based on the Mario franchise, named the Nintendo Court, is also featured in the GameCube version.' FROM games WHERE igdb_id = 230484 ON CONFLICT (game_id, language_code) DO NOTHING;
