INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow of the Colossus', 'An open-world action/adventure game in which a young wanderer, along with a stolen magical sword and his steed companion, trespasses a cursed land, makes a deal with an ancient being to bring a sacrificial victim back to life, and sets off to fulfill his end of the bargain, which involves tracking down and infiltrating the abodes of sixteen colossi and sacrificing them to achieve his goal.' FROM games WHERE igdb_id = 2207 ON CONFLICT (game_id, language_code) DO NOTHING;
