INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tear Ring Saga Series: Berwick Saga: Lazberia Chronicle Chapter 174', 'TearRing Saga Series: Berwick Saga, subtitled Lazberia Chronicle Chapter 174, is a game for the PlayStation 2 console. While it is officially the sequel to the original TearRing Saga: Utna Heroes Saga, the games are not significantly related by plot, and the Berwick Saga battle and skill systems borrow significantly less from Fire Emblem than the Utna Heroes Saga battle and skill system did; because of this, the two games barely resemble each other in terms of gameplay.' FROM games WHERE igdb_id = 80578 ON CONFLICT (game_id, language_code) DO NOTHING;
