INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychonauts', 'Psychonauts is a platform-adventure game developed by Double Fine Productions and released in 2005. It follows Razputin “Raz” Aquato, a young psychic who runs away from the circus to attend a summer camp for aspiring psychonauts. Players explore imaginative levels set inside the minds of different characters, each reflecting their mental states. Gameplay combines platforming, combat, and the use of psychic abilities such as telekinesis and levitation. The game was praised for its creativity, humor, and distinctive art style.' FROM games WHERE igdb_id = 1339 ON CONFLICT (game_id, language_code) DO NOTHING;
