INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeune Styliste 3: Star', 'Young Stylist 3 Star on PC lets you create the look of the stars. Imagine their outfits for a concert, a fashion show, or an interview on the Croisette... Rediscover the world of the Young Stylist collection with Anna, the faithful assistant. Apply makeup with professional precision: blush, eyeliner, lipstick... Cast your cast and stage your fashion show. Choose the decor, music, and order of appearances to bask in the glory.' FROM games WHERE igdb_id = 340014 ON CONFLICT (game_id, language_code) DO NOTHING;
