INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nascar-simracing', 807, '2005-02-15', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ydk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR SimRacing', 'NASCAR SimRacing, abbreviated NSR, is a computer racing simulator developed by EA Tiburon and released on February 15, 2005, by EA Sports for Microsoft Windows. The game includes all of the 2004 NEXTEL Cup Series tracks including Pocono Raceway as an unlockable like in NASCAR 2005: Chase for the Cup The game cover features the vehicles of Ryan Newman, Ron Hornaday and Chad Chaffin on the cover. The game features NASCAR''s top 3 series, the Nextel Cup, Busch, and Craftsman Truck Series. The game features a single-player career mode as well as multiplayer online gameplay. The game also features many paint schemes used during the 2004 and 2005 Cup Series; however the original release featured the 2005 cars replaced with their 2004 counterparts. This game was the last NASCAR game to be released for the PC by EA; the next NASCAR game for PC would be NASCAR The Game: 2013 by Eutechnyx' FROM games WHERE igdb_id = 807 ON CONFLICT (game_id, language_code) DO NOTHING;
