INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man: Maverick Hunter X', 'Mega Man Maverick Hunter X, known as Irregular Hunter X in Japan, is an enhanced remake of the original Mega Man X game released for the PlayStation Portable in 2005-2006. The game is also compatible and cross-playable with the PlayStation Vita via a PSN Download which was released at the PlayStation Vita''s launch on February 15, 2012. It has several new features and several redesigns.' FROM games WHERE igdb_id = 24275 ON CONFLICT (game_id, language_code) DO NOTHING;
