INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Story 2: Operation Rescue Woody', 'Toy Story 2 Operation: Rescue Woody! is a V.Smile game based on the 1999 Pixar film Toy Story 2. While Andy is away at summer camp, Woody is toynapped! Buzz Lightyear and his friends have to save Woody before Andy comes back. Let’s join Buzz and his friends on this exciting rescue adventure!' FROM games WHERE igdb_id = 77330 ON CONFLICT (game_id, language_code) DO NOTHING;
