INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokemon-advanced-cyber-poke-ball-2', 245422, '2005-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yaq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Advanced: Cyber Poké Ball 2', 'This is the second version of the Cyber Poké Ball, a simple RPG set in the Pokémon universe and contained within a handheld shaped like a Poké Ball. The units come in several colors and patterns. In the game, players explore a map to find wild Pokémon and battle them. A weakened wild Pokémon can be captured and added to the party; the player may own a maximum of three Pokémon at a time. Pokémon automatically evolve upon reaching certain level thresholds. Players may challenge area bosses, which will grant access to new parts of the world upon their defeat. They may also use the device''s connectivity features to battle other nearby players. Special chips, which came packaged with various Pokémon toys made by Bandai, could be inserted into the device in order to access new content.' FROM games WHERE igdb_id = 245422 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 245422 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
