INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '18 Wheels of Steel: Convoy', 'Take the wheel of a fast paced, high intensity trucking business. Start as a one man show, bidding on jobs, then build your fleet into an unstoppable convoy and deliver the goods. Grow your business and your fleet, but beware - your reputation is everything.' FROM games WHERE igdb_id = 31696 ON CONFLICT (game_id, language_code) DO NOTHING;
