INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The X Factor Sing', 'X-Factor is a single and multiplayer singing game. In real karaoke style, songs appear on your screen and you have to sing the right words at the right time. Onscreen indicators inform you what pitch you need to maintain at any given time. Hit the right notes for the right amount of time, and you''ll get high scores.' FROM games WHERE igdb_id = 84261 ON CONFLICT (game_id, language_code) DO NOTHING;
