INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Altered Beast', 'Altered Beast is a 2005 action-adventure beat ''em up video game for the PlayStation 2. The game is a remake of the 1988 arcade game Altered Beast. While the gameplay still involves the main character transforming into different kinds of beasts like in the original, the story, characters and setting are completely different, along with notable gameplay additions.' FROM games WHERE igdb_id = 19411 ON CONFLICT (game_id, language_code) DO NOTHING;
