INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexic HD', 'Hexic HD is the next puzzle hit from Alexey Pajitnov, the original creator of "Tetris." Rotate groups of three hexes to form clusters of like-colored tiles. Use bonus pieces and starflowers to boost your score and discover new ways to play. But watch out for bombs - clear them before they explode or it''s game over.' FROM games WHERE igdb_id = 2732 ON CONFLICT (game_id, language_code) DO NOTHING;
