INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crushed-baseball', 49306, '2005-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/guphxfvzqwpy7jj3qdxt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crushed Baseball', 'With its unique comic-book inspired art style, Crushed Baseball 2004 will offer fast-paced arcade gameplay that will appeal to both sports and non-sports gaming fans. With its over-the-top style, players will be able to power-up characters and give them superhuman abilities and special powers called "Mojo" abilities. For example, a pitcher might throw a pitch that acts as a buzz-saw and slices through the hitter''s bat; a batter may hit a ground ball that lodges itself in the field so it can''t be picked up, and a fielder might use their suction glove ability to suction the ball into their glove to record an out.' FROM games WHERE igdb_id = 49306 ON CONFLICT (game_id, language_code) DO NOTHING;
