INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('polar-golfer-pineapple-cup', 83298, '2005-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nbe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polar Golfer: Pineapple Cup', 'Relax and stroll down tropical fairways, surrounded by island flowers and grass huts in Polar Golfer: Pineapple Cup. It''s a lush new course full of pineapples and palm trees! Characters you met and clicked with in Polar Golfer are back in this Polynesian-style sequel. Yell "FORE" from fairways filled with molten lava and giant tiki heads. Ocean hazards and erupting volcanoes make this course challenging and fun. Swing with one paw and send your golf ball sailing over scorching lava rock! Reunite with Polar Golfer''s friends: Walrus, Gopher, and Santa, and meet all-new, comical characters like Hula Girl and Tiki Guy. Improve your score with power rings that keep you sailing in the right direction in Polar Golfer: Pineapple Cup!' FROM games WHERE igdb_id = 83298 ON CONFLICT (game_id, language_code) DO NOTHING;
