INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Tennis: World Tour', 'Virtua Tennis: World Tour is the PSP incarnation of Sega''s Virtua Tennis series. You can play as one of many professional tennis players, such as Roger Federer or Maria Sharapova, on courts around the world. In addition to Exhibition and Tournament modes, you can create a custom player and play through World Tour mode. Virtua Tennis: World Tour also lets you play stat-building minigames and challenge up to four other players in Versus mode.' FROM games WHERE igdb_id = 22312 ON CONFLICT (game_id, language_code) DO NOTHING;
