INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gushers-re-do-your-room', 372730, '2005-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coanqd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sczojl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gushers Re-Do Your Room', 'Gushers Re-Do Your Room or Gushers Place was an online Flash game/website created to promote the Fruit Gushers Re-Do Your Room sweepstakes that took place in the summer of 2005. Users would enter a lobby room, register a username and password, and were assigned a room number on a random floor. This room could then be customized with a wide array of pre-made furniture. New items could be obtained by entering codes found on specially marked Fruit Gushers snacks. An "Express Elevator" was available to allow quick access to a room you have already registered, and to enter other user''s rooms if they had the right floor, room number, and username. The game also included a unknown mechanic that would allow other users to "mess up" other''s rooms. Possibly with the usage of a mystery box that would explode or "gush" goo all over the room like in the commercial.' FROM games WHERE igdb_id = 372730 ON CONFLICT (game_id, language_code) DO NOTHING;
