INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman Begins', 'Step into the shadows of Gotham City’s perilous criminal underworld as DC Comics’ legendary Dark Knight in the Batman BeginsTM video game. Slated for release day and date with the Warner Bros. Pictures film, Batman Begins challenges players to use fear as their ultimate weapon. The game explores the origins of the Batman legend and the Dark Knight’s emergence as a force for good in Gotham. Gamers will play as both Bruce Wayne and his alter-ego, Batman, hunting evil-doers from the shadows, using strength, intellect and an array of high tech gadgets to fight the sinister forces that threaten the city, including classic villains Scarecrow, Ra’s Al Ghul and Carmine Falcone.' FROM games WHERE igdb_id = 3063 ON CONFLICT (game_id, language_code) DO NOTHING;
