INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inuyasha: Feudal Combat', 'Featuring all your favorite characters from the hit TV show, the first Inuyasha fighting game for the PlayStation 2 features a mission mode, a battle mode for versus gameplay, practice mode and a story mode. Featuring an original battle system, the game allows you to partner with another character, select the best formation system and develop and strengthen your fighting partnership, and destroy objects around you as you battle to take out the opposition.' FROM games WHERE igdb_id = 10256 ON CONFLICT (game_id, language_code) DO NOTHING;
