INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burnout Legends', 'Burnout: Legends takes the most explosive moments of the popular Burnout series of racing games, mashes them together and adds some new surprises -- giving you the best racing experience to come out for the DS. Use your car as a weapon and battle your way to the front of the pack - by taking out rivals and instigating spectacular crashes. Speed, depth and destruction are waiting for you, in the game of on-the-go automotive anarchy.' FROM games WHERE igdb_id = 10916 ON CONFLICT (game_id, language_code) DO NOTHING;
