INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('singstar-pop', 15092, '2005-05-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hpj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7fsy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: Pop', 'Be a Pop Superstar with SingStar Pop Featuring a chart-topping line-up of today’s best artists, songs and videos, SingStar Pop is the second release in the PlayStation2’s newest interactive singing franchise. With custom microphones in hand, singers perform along to 30 songs and videos from “Top 40” artists such as Rihanna, All American Rejects, Cyndi Lauper, Gorillaz, Snow Patrol, U2 and more, turning your living room into the pop concert of the year - 30 chart-topping songs and videos from today’s top artists. - Available as a Standalone SKU or bundled with two custom, high-quality microphones and the SingStar USB converter. - Multiple gameplay modes, including Solo, Freestyle, Pass the Mic, Battle and Duet, create a highly interactive social experience. - SingStar technology recognizes pitch, tone and rhythm to accurately score performances. - Record your favorite performances onto Memory Card for future playback. Customize and enhance playback with numerous audio effects. - Includes EyeToy USB camera compatibility: players can see themselves singing in place of the artist’s video. - Expandable Song Library: Disc Swap feature keeps the party rocking as different SingStar discs can be quickly changed.' FROM games WHERE igdb_id = 15092 ON CONFLICT (game_id, language_code) DO NOTHING;
