INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guild Wars: Collector''s Edition', 'In a world torn by conflict, where human kingdoms are all but destroyed and guilds sacrifice all for a chance to control the Hall of Heroes, a champion must rise from the ruins of a once-proud land to lead refugees from the ashes and fulfill an ancient prophecy. Will that hero be you? The Guild Wars Collector''s Edition box includes: - Exclusive in-game Divine Aura for your characters - Logitech Internet Chat Headset - Teamspeak Software (custom version) - Artbook "The Art of Guild Wars" with 128 Pages - Guild Wars Soundtrack CD' FROM games WHERE igdb_id = 142287 ON CONFLICT (game_id, language_code) DO NOTHING;
