INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Champions: Return to Arms', 'An action fantasy RPG that is the sequel to the 2004 Champions of Norrath: Realms of EverQuest, and with the same style of dungeon crawling and hack ''n'' slash, Champions: Return to Arms differs from its predecessor by offering the player the ability to fight for either ''good'' or ''evil''. With a variety of races and classes to create a character from, the player travels across different acts and different lands combating all sorts of enemies.' FROM games WHERE igdb_id = 10237 ON CONFLICT (game_id, language_code) DO NOTHING;
