INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tak: The Great Juju Challenge', 'The top teams from across the world have come to compete in the Great Juju Challenge. Representing the Pupanunu Tribe are Tak and Lok who will face great adversity in the form of Jujus, wild animals, and some menacing new tribes. Tak: The Great Juju Challenge is an innovative cooperative videogame that combines unique puzzles, time-based strategies, and a robust combat systems. Players will have to use all their skills to win this race against the toughest competitors and receive the grandest reward ever given by the Great Jujus!' FROM games WHERE igdb_id = 2780 ON CONFLICT (game_id, language_code) DO NOTHING;
