INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penguin Puzzle', 'Penguin Puzzle is a puzzle game where you slide colored ice cubes around to either create a 2x2 or 3x2 square of the same color, or match the bonus shape shown to the right. With every move, more ice cubes appear, so plan your moves well. Every five levels, a bonus level will fill the screen with ice cubes. Click on a block to remove all connected ice cubes of the same color. After removing those, the remaining ice cubes will fall down to take their place.' FROM games WHERE igdb_id = 208883 ON CONFLICT (game_id, language_code) DO NOTHING;
