INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Justice: Revenge of the Rednecks', 'Country Justice is a first person shooter for the PC that was published by Valusoft and is by developed Silverfish Studios in 2005. It is generally regarded to be the worst first person shooter ever made. In the game you play as Earl who sets out to find his missing goat, after it has disappeared and his wife (and sister) hypothesizes that it has been kidnapped.' FROM games WHERE igdb_id = 52303 ON CONFLICT (game_id, language_code) DO NOTHING;
