INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animaniacs: Lights, Camera, Action!', 'Recent account calculations have shown that Yakko, Wakko and Dot have cost Warner more money in accumulated damage than they have generated profit since their escape from the water-tower. The Board of Directors are now giving them one last chance to justify themselves. To set their accounts straight, Warner have now decided to shoot three Animaniacs feature films in one go!!' FROM games WHERE igdb_id = 6306 ON CONFLICT (game_id, language_code) DO NOTHING;
