INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titanic', 'Titanic (also known as Titanic 2005) is an unlicensed NES/Famicom game made by Nice Code/Dragon Co. and published by Shenzhen Nanjing Technology in 2005. It can also be found on certain plug & play systems, under a different name. You can choose to play as Jack or Rose, and your objective is to escape the ship.' FROM games WHERE igdb_id = 10842 ON CONFLICT (game_id, language_code) DO NOTHING;
