INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xump-the-final-run', 138434, '2005-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3c9q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scas6f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xump: The Final Run', 'XUMP is a puzzle game by Psilocybin Development. The game is simple but will keep you busy for hours, and thats a promise! The game consists of a 20x12 playfield which is filled with various types of blocks. Your job is to make the blue blocks disappear from the playfield by stepping on them. There are five main types of block, each of which behave differently. The first levels are for ''easy entertainment''. At first the levels are small, then get bigger and harder at each stage. Even if you do not read the instructions here, you should be able to handle the game when you start at level 1. To make everything a bit more tricky keep track of the time, but don''t panic. If you solve a level without fault you will get a ''well done''. This ''well done'' is worth one extra chance, otherwise you will just get a ''done'' without any bonus. A ''well done'' is the only possibility in this game to get an extra life. Xump has participated in the 16 Days Coding Competition.' FROM games WHERE igdb_id = 138434 ON CONFLICT (game_id, language_code) DO NOTHING;
