INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Soccer 06', 'For 06, the players are more responsive and crucial features like first touch control have been re-mapped in a way that makes more sense. When you want to throw freestyle moves or play the ball into a space of your choosing as a pass comes to you, just hold down the left shoulder button and point the analog stick to pull your move or use first touch.' FROM games WHERE igdb_id = 700 ON CONFLICT (game_id, language_code) DO NOTHING;
