INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('street-supremacy', 38456, '2005-04-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coahb6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scipib.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Supremacy', 'Unlike other Shutokou Battle series titles, the objective of Street Supremacy is to join a team, level up to become the team leader, recruit other rivals to join your team, and to take control of the various highways in Tokyo. The map area consists of the areas featured in Tokyo Xtreme Racer 3, including the C1 Loop, Shinkanjou, Wangan Line, Yokohane, and Yokohama routes. Each route is broken up into several zones, which are controlled by the rival teams. Rival teams in Street Supremacy include Rolling Guy, Fine Drive, Galaxy Racers, The Road of Justice, Departures, No Loser, Highway Outlaw, Free Way, Another Star, Unlimited, Neo Limited, Speed Masters R, and Wanderers (much like other Shutokou Battle titles, Wanderers have certain requirements that need to be met before challenging the player). Some bosses from the other titles appear in Street Supremacy as Wanderers by default. Street Supremacy is the only Shutokou Battle series title where rivals can change teams during the game and teams can disband during the game.' FROM games WHERE igdb_id = 38456 ON CONFLICT (game_id, language_code) DO NOTHING;
