INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party 7', 'You can play more than 80 new minigames in the most recent Mario-themed party game, Mario Party 7. Mario and pals needed some time off, but they forgot to invite Bowser on their cruise. You can battle against an angry Bowser or up to seven of your friends on a single GameCube system. Mario Party 7 includes a few new characters and brings back microphone support from Mario Party 6.' FROM games WHERE igdb_id = 2334 ON CONFLICT (game_id, language_code) DO NOTHING;
