INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fullmetal Alchemist: Dual Sympathy', 'Hagane no Renkinjutsushi: Dual Sympathy (Fullmetal Alchemist: Dual Sympathy as it is known in English) is the first in a series of Fullmetal Alchemist games to be released on Nintendo DS. A side scrolling action game, Dual Sympathy has the player manipulate alchemy skills using the stylus as you fight enemies, making use of standard attacks and special attacks based on the surrounding environment and items items located in the area. The story of the game follows the fifty one episode anime series with the same name. Connectivity bonuses can be unlocked by having the GBA Fullmetal Alchemist games in the GBA slot of the DS.' FROM games WHERE igdb_id = 19073 ON CONFLICT (game_id, language_code) DO NOTHING;
