INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Winnie the Pooh''s Rumbly Tumbly Adventure', 'Join Winnie the Pooh and his friends on five birthday-themed adventures. In Winnie the Pooh Rumbly Tumbly Adventures, you can play as Tigger, Piglet, Eeyore, and Winnie the Pooh. Find as many honey pots as you can, but beware of the mischievous Heffalumps and Woozles, who steal honey.' FROM games WHERE igdb_id = 4234 ON CONFLICT (game_id, language_code) DO NOTHING;
