INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('steel--2', 329915, '2005-02-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cav.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv7mq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel', 'The protagonist, Tomoya, was abandoned by his mother at a tender age. He was taken in by Honjou Arisa after a chance meeting. Four girl adoptees who had joined the Honjou family home for similar reasons also lived there. Though they were not related by blood, Tomoya treated the girls as if they were his siblings. They lived peaceful lives at the Honjou residence... but one day, he encountered a strange woman in town. She was wreathed in something that looked like iron – and upon seeing her figure, he remembered that he, too, had once harbored such a metallic augment. "Is that... your Anima?" A right arm turned to metal... A peculiar corpse discovered at school... A transfer student exuding dark mist... And a foreign warrior wreathed in thick steel armor... Tomoya''s peaceful life would soon begin to crumble as disaster came to visit him and his sisters. To protect them, he shall have to once again wreathe his right arm in Anima.' FROM games WHERE igdb_id = 329915 ON CONFLICT (game_id, language_code) DO NOTHING;
