INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest II: Luminaries of the Legendary Line', 'This game allows the player to control more than one character, and it is the first one in the Dragon Quest series to do so. The player controls his or her characters as they move in the game world. They can search treasure chests, talk and trade with villagers, equip weapons and armor, and cast spells.' FROM games WHERE igdb_id = 1813 ON CONFLICT (game_id, language_code) DO NOTHING;
