INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeons-dragons-dragonshard', 674, '2005-09-21', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yvl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsogq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons: Dragonshard', 'Dungeons & Dragons: Dragonshard is a real-time strategy role-playing video game, developed for Microsoft Windows by Liquid Entertainment, and published by Atari in 2005. It takes place in Eberron, one of the official Dungeons & Dragons campaign settings. The game combines elements of traditional real-time strategy gameplay with role-playing elements such as hero units, and questing. Dragonshard includes two single-player campaigns, single-player skirmish maps, and multiplayer support. The single-player campaign follows the struggles of three competing factions to gain control of a magical artifact known as the Heart of Siberys. Although Dragonshard was billed by Atari as "the first Dungeons & Dragons real-time strategy experience,"[2] Stronghold (1993) precedes it by over a decade.[3]' FROM games WHERE igdb_id = 674 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 674 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
