INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sly 3: Honor Among Thieves', 'Sly 3: Honor Among Thieves is a stealth-action platformer developed by Sucker Punch Productions and released for PlayStation 2 in 2005. The game follows Sly Cooper and his crew as they recruit new allies to help unlock the Cooper Vault while facing off against Dr. M, a former member of Sly’s family lineage. It introduces new playable characters, expanded mini-games, and a 3D mode with optional glasses.' FROM games WHERE igdb_id = 1800 ON CONFLICT (game_id, language_code) DO NOTHING;
