INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wildlife Tycoon: Venture Africa', 'From the back-catalog of Pocketwatch Games, 2005''s Wildlife Tycoon: Venture Africa was the game that started this indie''s journey. Expect the unexpected out of this unique Tycoon game -- There are no people to please, there is no money to horde, there are only animals. Packs of hungry lions, families of chattering baboons, and epic herds of wildebeests fill the ecosystems that players create and control.' FROM games WHERE igdb_id = 91661 ON CONFLICT (game_id, language_code) DO NOTHING;
