INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-hunter-freedom', 2269, '2005-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1po0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc78va.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Hunter Freedom', 'Known as "Monster Hunter Portable" in Japan, Monster Hunter Freedom is essentially a PSP version of the preceding expansion to the original game, Monster Hunter G. As such it features very similar content, reworked to be a portable experience. Monster Hunter Portable does not features Minegarde Town from Monster Hunter and Monster Hunter G, and was focused around local multiplayer rather than online. As such, the game was completely rebalanced to be more friendly to solo players. The game features a single new monster that was not in the series prior, Yian Garuga. The game revolves around the player completing quests and gathering materials to upgrade their equipment in order to advance. The more rare the items and equipment, the stronger the main physical aspects of the character will be. Unlike other hack ''n'' slash games, this game requires planning and skill in order to overcome large monsters instead of brute force. There are many weapons which the hunter can use to bring down the monsters, these are sword and shield, great sword, dual swords, hammer, lance, bowgun and the heavy bowgun. Each requires a variety of items to create which are acquired by completing quests, and collecting the spoils carved from monsters or found on the ground.' FROM games WHERE igdb_id = 2269 ON CONFLICT (game_id, language_code) DO NOTHING;
