INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('colosseum-road-to-freedom', 22456, '2005-03-17', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oto.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scke8j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colosseum: Road to Freedom', 'Taken into slavery, you are now a gladiator. Your only chance at freedom is to earn enough money in the arena to buy yourself back. Whether in a lowly arena on the outskirts of the Empire or in the Colosseum itself, a wide variety of opponents await: heavily armed charioteers, wild bulls, fellow gladiators and more. In a series of battles, from battle royales to one-on-one duels, you must entertain the crowds by spilling blood. After battles, it''s time to train. A series of minigames improves your attributes and your diet perfects your body. Study your rankings, play around with your special skills, and await the next battle. Colosseum: Road to Freedom is a self-described Action RPG, controlled in the third-person and works as a gladiator simulator.' FROM games WHERE igdb_id = 22456 ON CONFLICT (game_id, language_code) DO NOTHING;
