INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xanadu Next', 'Xanadu Next is an exploration-centric action RPG from Nihon Falcom, the acclaimed creators of the Ys and The Legend of Heroes RPG franchises. A late entry in their immensely popular Dragon Slayer series and a spiritual follow-up to the late ‘80s cult classic Faxanadu, Xanadu Next puts players in the shoes of a gravely injured knight given a new lease on life through ancient magic who must now seek a legendary sword called “Dragon Slayer” to ensure his survival.' FROM games WHERE igdb_id = 6296 ON CONFLICT (game_id, language_code) DO NOTHING;
