INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x3-reunion', 9319, '2005-10-28', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rkd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ypy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X3: Reunion', 'The Sequel to the award winning X2: The Threat introduces a new 3D engine as well as a new story, new ships and a new gameplay to greatly increase the variety in the X-universe. The economy of X3: Reunion is more complex than anything seen in the X-universe before. Factories are being built by NPCs, wars can affect the global economy, NPCs can trade freely and pirates behave far more realistically. Space just got a whole lot bigger with the addition of two new sectors and the introduction of the gargantuan Player HQ which allows many exciting new features including the ability to build your own ships and even give them customized space paint finishes. In addition to the new M7 battleship, there is an assortment of new weapons and onboard ship devices to use and explore.' FROM games WHERE igdb_id = 9319 ON CONFLICT (game_id, language_code) DO NOTHING;
