INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shinobido-way-of-the-ninja', 10899, '2005-11-10', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co490q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scstgv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinobido: Way of the Ninja', 'DEEP IN THE SHADOWS A NlNJA WAlTS TO STRIKE It is the 16th century. The once peaceful province of Utakata now lies in a state of despair. The elite ninja clan who once protected the region are all but dead and with no safeguard, Utakata‘s enemies are starting to stir. War is surely near. As the last of the Asuka Ninja you must rise up and choose a new path. Exact revenge on those who sought to end your clan and decide upon a new fate for the land. -Use Stealth or aggression to defeat your enemies -Combine your equipment to form over 150 weapons and items -Create maps and missions and transfer them to Shinobido: Tales of the Ninja on your PSP (PlayStation Portable) (sold separately)' FROM games WHERE igdb_id = 10899 ON CONFLICT (game_id, language_code) DO NOTHING;
