INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pariah', 'Pariah is a first-person shooter video game, developed by Brainbox Games, HIP Games and Digital Extremes. It was released on May 3, 2005 for Microsoft Windows and Xbox. It uses a modified version of the Unreal engine and the Havok physics engine. Pariah received mixed reviews from critics.[1]' FROM games WHERE igdb_id = 5979 ON CONFLICT (game_id, language_code) DO NOTHING;
