INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vicolumn', 78316, '2005-12-31', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ViColumn', 'ViColumn is, as one might guess, a re-implementation of SEGA''s Columns for the VIC-20, released in 2005. Blocks of three vertically arranged colours, out of a pallette of four, come dropping down from above, and must be placed on the bottom or on top of another block. By pressing fire, you can rotate the colours inside the block so as to fit in with the colours of other blocks already placed on the screen. If three or more adjacent blocks have the same colour on a row or column, that colour block is eliminated, making room for more blocks. Carefully laying down the blocks can lead to chain reactions. Unlike the original Columns, though, this implementation does not recognise diagonal colour combinations.' FROM games WHERE igdb_id = 78316 ON CONFLICT (game_id, language_code) DO NOTHING;
