INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advent Rising', 'Advent Rising is a story driven science fiction third person action adventure game developed by GlyphX Games. Written by author Orson Scott Card and published by Majesco Entertainment. Advent Rising started as a trilogy, but due to poor critical reception and poor sells the sequels were cancelled. There was a PSP title in the works called "Advent Shadow" that was also cancelled. Due to an epic story and fun gameplay, Advent Rising has acquired a cult following and is considered and underrated classic by fans.' FROM games WHERE igdb_id = 5716 ON CONFLICT (game_id, language_code) DO NOTHING;
