INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of Honor', 'As King, it is your duty to lead your people in their struggle to raise your kingdom from its humble beginnings to a position of power and prestige. War, diplomacy and a burgeoning economy are the means by which you increase your power and expand your influence. A unique Knight-management system will offer you brand new possibilities to enhance your personal strategy.' FROM games WHERE igdb_id = 2040 ON CONFLICT (game_id, language_code) DO NOTHING;
