INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sanyou-pachinko-paradise-11-shin-umi-to-saraba-gintama-no-ookami', 326852, '2005-02-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97jl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanyou Pachinko Paradise 11: Shin Umi to Saraba Gintama no Ookami', 'Pachinko Paradise 11 is one of the many titles in Irem''s long-running pachinko simulation series. It features faithful 3D recreations of two pachinko machines made by Sanyo Bussan: CR Shin Umi Monogatari M8Z and CR Shin Umi Monogatari M6Z. There are two modes available: Tsūjō (Normal) mode allows the player to modify a wide range of settings for each machine, while Jissen (Battle) mode challenges the player to win as many balls as possible on the default settings with a limited starting pool and time limit. There is also a View mode where the various animations that play on the in-game display can be freely viewed. Pachi-Pro Fūunroku returns again with Pachi-Pro Fūunroku 3: Saraba Gindama no Ōkami, concluding the storyline introduced in the first title. The game returns to the adventure style of the first two titles, but adds a much greater degree of freedom to affect the outcome of the story. There are a large number of locations to visit apart from the pachinko parlors, and there are several very different endings that can be reached depending on the player''s choice. The relationship system has also returned with several new girls to pursue, for a total of eleven.' FROM games WHERE igdb_id = 326852 ON CONFLICT (game_id, language_code) DO NOTHING;
