INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendogs: Shiba & Friends', 'Nintendogs is a realtime pet simulation video game developed and published by Nintendo for the Nintendo DS handheld video game console. It was first released in Japan, and was later released in North America, Australia, Europe, and other regions. It was originally released in three different versions: Dachshund & Friends, Lab & Friends (Shiba & Friends in Japan), and Chihuahua & Friends. It has been re-released twice since then, first as a bundled release with a special edition Nintendo DS with a new version called Nintendogs: Best Friends, and then later as Nintendogs: Dalmatian & Friends.' FROM games WHERE igdb_id = 278844 ON CONFLICT (game_id, language_code) DO NOTHING;
