INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Quest', 'More than an addictive puzzle game - a true cinematic experience. After three dragons wreak havoc over the empire, young Kwazi must use an ancient set of Mah Jong tiles to restore balance. Enjoy sweeping animations as you help Kwazi journey through the Orient, meet wise animal guides, and use an amazing array of special tiles to solve tricky puzzles. In addition to this great story, you can also enjoy your favorite layouts in Classic-style play, and whole new challenges in Puzzle-style play.' FROM games WHERE igdb_id = 286435 ON CONFLICT (game_id, language_code) DO NOTHING;
