INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'London Racer: Destruction Madness', 'London Racer: Destruction Madness is a racing game, featuring 12 environments spread across 10 European cities. Each environment has 5 tracks for a total of 60 tracks, which can all be played in 4 different time settings. In these cities it is your task to cause as much mayhem and destruction as possible. Compete in races and take out your opponents so they will never reach the finish line, with a wide array of weaponry available. Or take on your opponents in a Destruction Derby style arena.' FROM games WHERE igdb_id = 15438 ON CONFLICT (game_id, language_code) DO NOTHING;
