INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cloud', 'A 2005 puzzle game developed by a group of Japanese students, Cloud centers upon a small boy who dreams of flight whilst sleeping in his hospital bed. The player controls the boy''s dream avatar as it soars over a collection of small islands. The primary focus of the game is to gather and manipulate clouds in order to create various shapes and ward off incoming rain clouds.' FROM games WHERE igdb_id = 93270 ON CONFLICT (game_id, language_code) DO NOTHING;
