INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carl the Caveman', 'In this arcade game you have to help a caveman find all the mushrooms and collect all the jewels in the maze. This needs to be done as carefully as possible - some levels are inhabited by both monsters and poisonous toadstools, who themselves are not averse to trying to eat a gaping mushroom picker.' FROM games WHERE igdb_id = 281419 ON CONFLICT (game_id, language_code) DO NOTHING;
