INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chou Jinsei Enjoi! Tamagotchi Plus', 'The Chou Jinsei Enjoi Tamagotchi Plus also known as the Entama for short, is a Tamagotchi virtual pet that debuted in Japan on November 23, 2005. It was the first Tamagotchi release to include Internet functions, and introduced a new shell design that features an antenna with a ball at the tip.' FROM games WHERE igdb_id = 229952 ON CONFLICT (game_id, language_code) DO NOTHING;
