INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Challenge 2006', 'Ski Challenge 2006 is an alpine skiing game. The game includes the famous alpine downhill tracks of Bormio, Val Gardena, Kitzbühel and Wengen. The goal for the players is to climb the leaderboards by getting the fastest times. Three day events were held on each track to determine race winners who would win physical prizes.' FROM games WHERE igdb_id = 87785 ON CONFLICT (game_id, language_code) DO NOTHING;
