INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Girl Army', 'Amy is interested in hanging around with Sonic, but Sonic is having none of it as he makes up an excuse to avoid Amy. As Sonic runs away, Amy tries to follow him but she get''s lost along the way and get''s attacked by one of Eggman''s Minions. Determined that she does not need Sonic''s or the others help she adventures off to foil Eggman''s plans on her own.' FROM games WHERE igdb_id = 324699 ON CONFLICT (game_id, language_code) DO NOTHING;
