INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House', 'In 1970, there was a house that belonged to a family of four. But inexplicably, the family were all found dead in what was declared a mass suicide. Since then, nobody had dared to enter the house in the fears that it may be haunted, not willing to risk the same mysterious death that the family did. The player''s goal is to enter the house and venture through the five rooms.' FROM games WHERE igdb_id = 204651 ON CONFLICT (game_id, language_code) DO NOTHING;
