INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2005 Minigame Multicart', 'Atari 2600 fans Chris Walton (cd-w), Fred Quimby (batari), Bob Montgomery (vdub_bobby), and Zach Matley (Zach) submitted several 1K entries for the 2005 Minigame Competition. They have now teamed up to release their seven 1K games in a single 2005 Minigame Multicart, complete with an on-screen menu that allows easy selection of the games as well as instructions.  The included games are: Hunchy, Jetman, Nightrider, Zirconium, Rocket Command, M-4, and Marble Jumper' FROM games WHERE igdb_id = 40792 ON CONFLICT (game_id, language_code) DO NOTHING;
