INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie and the Chocolate Factory', 'Step inside the magical world of Willy Wonka''s famous chocolate factory. Based on the Warner Bros. film and the classic novel by Roald Dahl, Charlie and the Chocolate Factory lets you delve deep inside the factory to relive the classic story as Charlie Bucket. Find a golden ticket and, along with four other children, win a personal tour of Willy Wonka''s factory as guided by the notorious and reclusive candy maker himself. Discover what happens after the other children, greed-driven and unrestrained, wreak havoc throughout the factory.' FROM games WHERE igdb_id = 22449 ON CONFLICT (game_id, language_code) DO NOTHING;
