INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: Magical Melody', 'Flower Bud Village wasn''t a blossom of a burg when you bought a plot of land. Now newcomers depend on the bounty from your land for their livelihoods. It''s up to you to create a farm, raise a family and build a village in the most challenging Harvest ever! -Play as a girl or as a boy! -Buy farm land next to a river, along a seashore or in a village! -Plant crops, raise livestock, dig for gems or just fish! -Beat your farming rival in the fields and at the festivals! -Unlock hidden multiplayer mini games!' FROM games WHERE igdb_id = 3386 ON CONFLICT (game_id, language_code) DO NOTHING;
