INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saturday School', 'Vivi finds out that her friends are going to the beach the same morning that she is in Saturday school detention. Will she escape? Can she get out before it''s too late? Originally created for the first-ever "One Room, One Week" Competition, April 2005. The game was also nominated for Best Short Game in the AGS Awards 2005.' FROM games WHERE igdb_id = 171557 ON CONFLICT (game_id, language_code) DO NOTHING;
