INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('suzuki-tt-superbikes-real-road-racing', 20211, '2005-09-03', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/h9wmdsgvstmlnimizsyl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6yvx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suzuki TT Superbikes: Real Road Racing', 'Suzuki TT Superbikes features more than 50 vehicles from all over the world, and includes the world famous 37.73 mile Isle of Mann racetrack. For the highest level of realism possible, the course itself has been mapped using data supplied by the government and data captured by the development team. In addition to the traditional racing, the game also features a "Mad Sunday" mode that brings riders from all over the world to test their chops on the mountain. Supplementary modes, such as two-player split-screen and sidecar multiplayer are also included, as are bikes from all classes -- from 125cc all the way to the F1 1000ccs!' FROM games WHERE igdb_id = 20211 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 20211 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
