INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('devil-kings', 22568, '2005-07-21', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wzcz47nffh7yfjucvtbd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil Kings', 'Devil Kings is in the same vein as the Dynasty Warriors series. Whereas in Dynasty Warriors, however, Koei focuses on ancient Chinese history, Devil Kings focuses more on feudal Japan, but with a fictional setting with the ability to use modern day weapons such as chain guns and shotguns as well as fighting legendary and fictional characters from the past. The story takes place as the Devil King, a king possessed by the soul of the Devil, has unleashed an unholy army on the world to bend it to his will as the player must stop him along with many of his minions including his wife Lady Butterfly, his general the Red Minotaur, as well as loyal assassins Scorpio and Venus. The gameplay is more arcade hack-and-slash style, with the ability of using magic spells to wipe out entire waves of enemies and as mentioned before, the ability to use modern day weapons along with historical weapons such as spears, swords among others. There are six playable characters to use as well, each with their own story told in CG and anime cutscenes as well as two modes of play, Conquest (the main story of the game) and Free Mode (where players can play in any unlocked stage they have completed).' FROM games WHERE igdb_id = 22568 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 22568 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
