INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curious George Comes Home', 'Whether he''s racing a sailboat, running errands in town or visiting the zoo, Curious George always manages to get himself in a bind. Now, that ever-so-mischievous monkey is in trouble again...and only you can help him!! This critically acclaimed CD-Rom invites children on a free wheeling romp through the friendly and familiar world of Curious George. By actively participating in an ever-changing story- choose places to go, characters to visit and things to do. Children learn storytelling and problem solving in a creative, fun-filled environment.' FROM games WHERE igdb_id = 145899 ON CONFLICT (game_id, language_code) DO NOTHING;
