INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winnie the Pooh: The Honey Hunt', 'Winnie the Pooh: The Honey Hunt is a V.Smile game about Winnie the Pooh. In this game, Join Winnie the Pooh and his friends on this fantastic adventure where preschoolers learn the alphabet, numbers, shapes, vocabulary and much more. Help Pooh solve puzzles and collect as many honey pots as possible on the way to the party! Don’t forget to look out for the secret areas where Pooh can meet his friends and find more honey pots!' FROM games WHERE igdb_id = 78484 ON CONFLICT (game_id, language_code) DO NOTHING;
