INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maniac Mansion Mania', 'Maniac Mansion Mania is a series of Fan Sequels created by LucasFan from 2005 onwards. They are based on Maniac Mansion and sometimes Day of the Tentacle. The game involves Maniac Mansion characters in a unique style that is spread out episodically, like a TV series. The episodes are thus arranged in seasons, though there are also non-sequitur specials. Most episodes are comedic.' FROM games WHERE igdb_id = 279026 ON CONFLICT (game_id, language_code) DO NOTHING;
