INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Collapse! II Platinum', 'One of the most popular and addictive games to ever hit the web goes Platinum! Now with over 120 challenging puzzles, this updated edition also includes all new blocks, music, sound effects and more! Even post your scores to the Global High Score list and see how you rank with other players! Collapse fans will also find the full original Collapse, with enhanced graphics, sound effects and some surprises. The ultimate version of a classic hit, go Platinum today!' FROM games WHERE igdb_id = 194721 ON CONFLICT (game_id, language_code) DO NOTHING;
