INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogger: Helmet Chaos', 'Frogger returns in an all-new platform game, Frogger Helmet Havoc. In the amphibious hero''s latest adventure, Frogger must stop an evil force that threatens his home, Firefly Swamp, and the nearby kingdom of Bunnington Hollow. To stop Dr. Wani and his destructive mining efforts, you must help Frogger hop and dodge his way to the mastermind''s lair. Frogger has unique abilities that allow him to climb walls, double-jump, tongue-grab, and more.' FROM games WHERE igdb_id = 11481 ON CONFLICT (game_id, language_code) DO NOTHING;
