INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('green-green-3-hello-goodbye', 294620, '2005-08-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co806e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrl45.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Green Green 3: Hello, Goodbye', 'It has been a year since the Kanenone Gakuen transitioned into a co-ed school, integrating female students into a previously all-male high school. The school closure riots that followed were temporarily settled and the summer vacation was coming to an end by August. Yuusuke and Futaba are still fighting as usual, but they managed to keep it afloat. Everything seemed normal again, until suddenly... a fire broke out in the girls'' dormitory! And now the girls have to live alongside the boys in their dormitory. Yuusuke tries his best to make love amid all this, but he is now in trouble when a girl he has known since childhood shows up, and he starts to share a room with twin sisters! An unprecedented ordeal looms before the two of them! This is the final part of the series, filled with joy and conflict!' FROM games WHERE igdb_id = 294620 ON CONFLICT (game_id, language_code) DO NOTHING;
