INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('imperivm-iii-great-battles-of-rome', 290, '2005-05-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ss8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hkni9eplg6cz3dyvmrqv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperivm III: Great Battles of Rome', 'Imperivm: Great Battles of Rome is a sequel to RPG/RTS games Celtic Kings: Rage of War and Celtic Kings: The Punic Wars. The game, released in May 2005, was developed by Haemimont. The game contains various civilizations to choose from, among them are: Rome (Imperial and Republican), Egypt, Germania, Brittania, Iberia, Gaul and Carthage. It has a more elaborate hero system over its predecessor. The game focuses on tactics, troop mobility and terrain topography rather than sheer strength of numbers for winning battles. Though resources are important there is less relevance in gathering them than in other real-time battle games. Instead of sending an army of servants to mine, lumber, collect food or gather any other kind of resources these are generated at a constant rate directly proportional to the inhabitants of a population center. There are 3 player modes to choose from: Conquest: The battles involved on this game are focused on raising an empire by conquering all the known ancient world, the user can choose any of the available civilizations (see below) to do so. Rome''s Greatest Battles: A good amount of effort has been dedicated to historical accuracy; not only on the graphics but on the story line of this pre-built scenarios on which the player can live Rome''s defining moments, from The Battle of Zama which marked the final and decisive end of the Second Punic War to the rebellion of Marcus Antonius and Cleopatra. Custom Game: These feature is always present in modern day real time tactic and strategy games, it can be used to practice against computer opponents on custom made scenarios or to go on-line and battle against other human players' FROM games WHERE igdb_id = 290 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 290 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
