INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bone: Out From Boneville', 'After an attack by a swarm of locusts leaves Fone Bone lost in the mountains, he sets out to find his cousins, with a little help from a mysterious red dragon, a couple of talking bugs, and a pretty girl named Thorn. But with hungry rat creatures on his tail, will Fone Bone ever make his way back to Boneville?' FROM games WHERE igdb_id = 10059 ON CONFLICT (game_id, language_code) DO NOTHING;
