INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MetalHeart: Replicants Rampage', 'Metalheart: Replicants Rampage is a role-playing game with a turn-based combat system and a huge game world designed in classical cyberpunk style.The characters live in the dark post-apocalyptic world inhabited by four different races: humans, mutants, cyborgs and mysterious nomads. The player can form a party of up to 6 members with characters belonging to any of the four races. To complete some quests, a player will have to hire different specialists proficient in some particular skill, like snipers, demolishers, welders and many more.' FROM games WHERE igdb_id = 69749 ON CONFLICT (game_id, language_code) DO NOTHING;
