INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digby''s Donuts', 'Join Digby as he opens a chain of donut shops in Digby''s Donuts. Catch, stack and drop colorful donuts to form matches while earning big tips. As Digby''s new employee it''s your job to catch the donuts when they come fresh out of the oven, and stack them in the display counter. Stack them in groups of three by frosting color and they''ll disappear down the customer''s throats, earning you big tips. Digby''s Donuts is a deliciously addictive (and non-fattening) treat for the whole family!' FROM games WHERE igdb_id = 122893 ON CONFLICT (game_id, language_code) DO NOTHING;
