INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Star: Moe Drill', 'Based off the popular Lucky Star manga, Lucky Star Moe Drill is an educational game that features puzzles and quizzes picked from math, vocabulary and memory tests. The player''s main objective is beating other characters in quizzes. The game features the voice cast from the Lucky Star Drama CDs, due to its release prior to the anime.' FROM games WHERE igdb_id = 72618 ON CONFLICT (game_id, language_code) DO NOTHING;
