INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Risk Battleship Clue', 'Risk / Battleship / Clue is a compilation of board games developed by Gravity-i and published by DSI Games for Game Boy Advance. The game contains three digital recreations of real world Hasbro board games. The games use the original board games rules with some slight variation options available in games such as Battleship allowing for different ways to play.' FROM games WHERE igdb_id = 138001 ON CONFLICT (game_id, language_code) DO NOTHING;
