INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantis', 'Atlantis is a marble-popping game. Move your mouse left or right to aim the launcher and press the button to fire. You must complete rows of three or more of the same colored marbles to clear them. You must clear all marbles before they reach the exit or you will lose a life. If you lose all your lives, the game is over. The launcher holds two balls at the same time and these can be swapped, if you wish.' FROM games WHERE igdb_id = 13345 ON CONFLICT (game_id, language_code) DO NOTHING;
