INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Tycoon', 'City Tycoon is a unique simulator of city construction and development. Create your own city, solve the pollution problems, fight against criminality, fires, unemployment, energy lack and growth of demands of your citizens. In this game you can construct such buildings as nuclear energy stations, police departments and bus stops to make your city develop and flourish.' FROM games WHERE igdb_id = 138127 ON CONFLICT (game_id, language_code) DO NOTHING;
