INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legerdemain', 'A surreal fantasy RPG inspired by roguelike games and interactive fiction. Become a magician in the world of Phenomedom! Escape from prison! Learn rituals! Collect paragraphs! Converse with conjoined twins! Do battle with wild and original enemies, including pookahs, imp-imps, and boogadah dream porridge. Altogether there are dozens of areas to explore, hundreds of original monsters to slay, and nearly two hundred citizens brimming with lies and idle gossip.' FROM games WHERE igdb_id = 246162 ON CONFLICT (game_id, language_code) DO NOTHING;
