INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mensalão, O Jogo', 'Mensalão, O Jogo is a game based on the Mensalão scandal where you need to consult the records of the testimony of the Parliamentary Commission of Inquiry and find the four suspects who will be indicted in the ensuing administrative process, with the purpose of hunting down their respective mandates.' FROM games WHERE igdb_id = 221252 ON CONFLICT (game_id, language_code) DO NOTHING;
