INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under Siege', 'The game begins at the 1995 Cave of the Patriarchs massacre. The player takes on the role of Ahmed, who must incapacitate the shooter Baruch Goldstein, and subsequently fight Israeli forces. The player then takes the role of a 13 year old boy named Mann. Mann steals a flag from the back of a Merkava tank, and is killed by the enraged tank crew.' FROM games WHERE igdb_id = 95467 ON CONFLICT (game_id, language_code) DO NOTHING;
