INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bunker', 'Ronin golfer Mike Roman just wants to play golf, but when the evil sorcerer Manlocke miniaturizes him and traps him in the bunker, he must utilize his wits and his golf club in order to escape... ...or he may never be able to play golf again. This game was the winner of the June 2005 MAGS competition.' FROM games WHERE igdb_id = 171794 ON CONFLICT (game_id, language_code) DO NOTHING;
