INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Dragon Dream!', 'One Piece: Dragon Dream is a Japanese action board game for the Game Boy Advance console featuring characters from the popular anime and manga series One Piece. This game is a sequel to the Playstation game One Piece Ocean''s Dream. The games had also been made into a filler arc called the Ocean''s Dream arc, which has a similar storyline as the games. The game was developed and released in April 28th, 2005 by Bandai.' FROM games WHERE igdb_id = 49737 ON CONFLICT (game_id, language_code) DO NOTHING;
