INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Super Police', 'The rise of high-speed traffic crime in Japan and the USA has resulted in the world''s first rapid-response armed highway police force. Terrorists beware the WORLD SUPER POLICE! Choose from the cream of the police driving pool, equip your vehicle with the latest military-grade weapons and take to the city streets in search of criminals too hardcore for the highway patrol. Only you have the hardware and the skill to bring them in!' FROM games WHERE igdb_id = 43479 ON CONFLICT (game_id, language_code) DO NOTHING;
