INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nu, pogodi! Vypusk 4: Dogonyalki', 'A fun children''s arcade invites you to take part in the adventures of the famous couple of mischievous people - the Wolf and the Hare. Players are waiting for eight exciting levels, each of which consists of several funny episodes. Several difficulty levels suitable for both beginners and experienced Hares. Passing the game, the guys will learn an exciting story with an unexpected ending.' FROM games WHERE igdb_id = 232862 ON CONFLICT (game_id, language_code) DO NOTHING;
