INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Scorpion King', 'Memnon''s legions are spreading like plague over the land, massacring the free tribes that dare to oppose his rule. Hired by the leaders of the free tribes, you play as Mathayus, out to assasinate Memnon''s sorceress, Cassandra, only to kidnap and fall in love with her instead. When Cassandra returns to Memnon to save innocent lives, you must go back to rescue her and eventually face and defeat Memnon to fulfill your destiny and become the Scorpion King!' FROM games WHERE igdb_id = 185900 ON CONFLICT (game_id, language_code) DO NOTHING;
