INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the Abyss: Mieu no Daibouken', 'Mieu no Daibouken is an action role-playing game starring Mieu, the mascot of Tales of the Abyss. A total of twelve dungeons are available to the player for download. Mieu, using his abilities gained from the Sorcerer''s Ring, is supposed to reach the bottom of the dungeon, at which point one of the characters from Abyss will give the player a password. This password can be redeemed in Tales of the Abyss for items.' FROM games WHERE igdb_id = 294607 ON CONFLICT (game_id, language_code) DO NOTHING;
