INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iwai Keitai Kaitsuu! Tamagotchi Plus Akai', 'Keitai Kaitsuu Tamagotchi Plus Akai is a Japanese Tamagotchi released in July 2005. It is a themed re-release of the Keitai Kaitsuu Tamagotchi Plus featuring new characters, content, gameplay and a new base location, Makkakka Town. Makkakka Town is a town on the Tamagotchi Planet and the home of the Akai Tamagotchi, a unique type of Tamagotchi that emit a red glow.' FROM games WHERE igdb_id = 229951 ON CONFLICT (game_id, language_code) DO NOTHING;
