INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fairly OddParents: Clash With the Anti-World', 'Cosmo, Wanda and Timmy Turner set out on a zany new adventure as they are pitted against their nemesis, Mr. Crocker, and evil anti-fairies who have broken into Dimmsdale. On the unluckiest day of year, Friday the 13th, it''s up to Timmy and his Fairy God Parents to use their quick wit and bountiful wishes to defeat the anti-fairies and foil Crocker''s plan to take over the world.' FROM games WHERE igdb_id = 18256 ON CONFLICT (game_id, language_code) DO NOTHING;
