INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galidor: Defenders of the Outer Dimension', 'A 3D Action platformer video game tie-in to the TV Show/LEGO Toyline of the same name. It was originally being developer for PS2 and Gamecube consoles in 2002 but never released, leaving only the GBA game in it''s stead. It would eventually release for Windows PC in 2005 as a bargain title in the UK, usually bundled with other LEGO games at the time. It was later included in the 2007 "10 LEGO PC Games Collector''s Box".' FROM games WHERE igdb_id = 316808 ON CONFLICT (game_id, language_code) DO NOTHING;
