INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starshine Legacy Episode 4: The Riddle of Dark Core', 'Alex is having trouble with the teachers at school when her bullied brother James call her for help. The bully Katja agrees with leaving James alone if Alex can beat her in the old Scarecrow Race upon Scarecrow Hill. Alex agrees to race with her horse Tin-Can, but she is soon forced to learn more about her and her friends newfound powers when James mysteriously disappears the very next day.' FROM games WHERE igdb_id = 196739 ON CONFLICT (game_id, language_code) DO NOTHING;
