INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Saga Edition: Lightsaber Battle Game', 'Star Wars: Saga Edition: Lightsaber Battle Game is a plug''n''play game released in 2005, shortly after Star Wars: Episode III Revenge of the Sith. It lets the player use a wireless lightsaber to "defeat" enemies from the Star Wars saga. The game claims to be from the point of view of a Jedi the player names, but most of the events occurred to Jedi Obi-Wan Kenobi.' FROM games WHERE igdb_id = 255561 ON CONFLICT (game_id, language_code) DO NOTHING;
