INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mario-kart-arcade-gp', 45160, '2005-10-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21z5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/okwpwoarcnofmlnlopah.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart Arcade GP', 'Mario Kart Arcade GP is an arcade-only iteration of Nintendo''s Mario Kart series, developed by Namco. Designed for the Triforce arcade board (also used for F-Zero AX), players can race as one of eleven characters on twenty-four tracks. On certain machines, for an additional fee, a player''s data can be saved on a magnetic card which can be inserted into the machine again later to retain unlocked items and records. Nintendo''s limited role of development was mainly isolated to ensuring that it was a worthy title for the established franchise. This game''s arcade cabinet houses a camera that will take a photograph of the player''s face. The photo can be customized and then will be displayed above the player''s character during multiplayer races. The game is noted for being the first Mario Kart to feature playable crossover characters: Namco''s Pac-Man, Ms. Pac-Man and Blinky. The game''s sequel also featured Mametchi, a character from the Tamagotchi games. The third installment included Don from the Taiko no Tatsujin franchise.' FROM games WHERE igdb_id = 45160 ON CONFLICT (game_id, language_code) DO NOTHING;
