INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Truck Stunt Rally', 'Monster Truck Stunt Rally is a relaxing game in which you get the chance to drive a monster truck and have as much fun with it as you want. There are no actual rules or restrictions, except for the occasional fence that stops you from falling off the map. In essence, the goal is to push the car to its limits and see whether you have what it takes to perform daring stunts without destroying the vehicle in the process.' FROM games WHERE igdb_id = 146435 ON CONFLICT (game_id, language_code) DO NOTHING;
