INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MVP Baseball 2005', 'MVP Baseball 2005 is a baseball video game developed and published by Electronic Arts. It features then-Boston Red Sox left fielder Manny Ramirez on its cover. The game features full Major League Baseball, Minor League Baseball, and Major League Baseball Players Association licenses. It holds the 98th spot on IGN''s reader''s choice top 100 games ever as of 2006. As with previous versions of the game, the announcers are Duane Kuiper and Mike Krukow, real-life announcers for the San Francisco Giants.' FROM games WHERE igdb_id = 796 ON CONFLICT (game_id, language_code) DO NOTHING;
