INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaotix of Tomorrow', 'Chaotix of Tomorrow is a fan made Sonic RPG made by Magnus Andersson using RPG Maker 2000, it stars the Chaotix crew featuring the return of Mighty. The game was later updated in 2006 to add better graphics and new features. The creator originally did not plan to create a sequel to the game, but a sequel was made anyway titled Twisted Mettle.' FROM games WHERE igdb_id = 246723 ON CONFLICT (game_id, language_code) DO NOTHING;
