INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robotragedy', 'My game is called ROBOTRAGEDY, and is the story of a little robot who can''t go to the living room to see the show of Robotinna, a robotic singer our little buddy loves. Once he gets to the living room he sees on the TV that Robotinna has been kidnapped and then he goes out to rescue her.' FROM games WHERE igdb_id = 171546 ON CONFLICT (game_id, language_code) DO NOTHING;
