INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-treme Quads', 'Start your engines! X-Treme Quads features wild quad bike racing over even wilder terrain. So hold on tight! There are miles and miles of unrelenting track to cover before you can be crowned the champion, and the only guarantee is that the ride is going to be extreme! - 12 Xtreme quad bikes to choose from - 9 Xtreme racing tracks - Xtreme terrain and jumps to test you - Xtreme AI competitors to try and beat' FROM games WHERE igdb_id = 66924 ON CONFLICT (game_id, language_code) DO NOTHING;
