INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('front-mission-2089', 1504, '2005-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hf5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scka2q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Front Mission 2089', 'Front Mission 2089 is a tactical role-playing game developed by Square Enix Co., Ltd., MSF, and Winds, and was published and released in Japan by Square Enix Co., Ltd. in 2005 and 2008 for the mobile phones. The game was released on March 7, 2005, October 27, 2005, and June 18, 2008. Front Mission 2089 borrows many of the gameplay mechanics found in Front Mission. The video game progresses in a linear manner: watch cut-scene events, complete missions, set up their wanzers during intermissions, and sortie for the next mission. Missions in Front Mission 2089 are traditional tactical RPG fare, ranging from destroying all enemy targets to protecting a particular allied target. Due to its mobile phone format, the story of Front Mission 2089 is told through episodic content; new episodes were released for download on the video game''s official website on a bi-weekly basis. A returning feature in the game is the Arena. Like in Front Mission, players can fight other players to win monetary rewards. Mission rankings also make a return; based on the scoring system of Front Mission 3, players can earn new parts and wanzers by doing well during missions. Another returning feature is briefings. Lastly, players can choose to play two unique scenarios - one with the Oceania Cooperative Union (O.C.U.), and one with the United States of the New Continent (U.S.N.).' FROM games WHERE igdb_id = 1504 ON CONFLICT (game_id, language_code) DO NOTHING;
