INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpinDrive Ping Pong', 'SpinDrive Ping Pong puts players at the heart of realistic game play in which you battle your opponents for the top ranking title. SpinDrive Ping Pong''s fast-paced, exciting and realistic Ping Pong matches can be played in three different modes: Tournament Mode puts you in a competitive knockout competition, Rally Mode lets you enjoy a thrilling rally and in Exhibition Mode, you can start a single match straight away! Are you able to smash and spin your way to the top and become a world-ranking Spin Drive Ping Pong player?' FROM games WHERE igdb_id = 43354 ON CONFLICT (game_id, language_code) DO NOTHING;
