INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol. 27: Houkago no Love Beat', 'Houkago no Love Beat is a Japanese-only PlayStation 2 otome game (also referred to as GxB games) released on June 10, 2004. A notable feature of the game is the integration of real J-pop songs into the gameplay, and the ability to watch and listen to the songs again once you have mastered them in-game, as well as the fact that the main character has a voice (many otome games'' main characters are not voice acted).' FROM games WHERE igdb_id = 56957 ON CONFLICT (game_id, language_code) DO NOTHING;
