INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meta--1', 260065, '2005-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6w1d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnr5d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meta', 'A parody of amateur adventure design, this metagame consists of a simple treasure hunting game, and a complex editor needed to complete it. The editor and its assistant Cuppit are all part of the game; anyone involved in game or level design should appreciate the humor. The editor is an exercise of twisted logic and lateral thinking. You have to see it to believe it; with its offbeat controls, inventory items that kill you, and intentional misspellings, it''s the weirdest thing since sliced bread! META is based on Adventure Game Studio, the platform for most of our games, and is runner-up for two AGS Awards.' FROM games WHERE igdb_id = 260065 ON CONFLICT (game_id, language_code) DO NOTHING;
