INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One', 'One is the first ever AAA Nokia N-Gage fighting title. You will be tested in incredible locations, against well-trained bosses with furious gangs who master different fighting techniques and styles. ONE breaks the boundaries of mobile gaming. Experience amazing 3D fighting with stunning motion-captured animations. This is the first ever mobile game with mocap, and includes real-time multiplayer fighting over bluetooth.' FROM games WHERE igdb_id = 6267 ON CONFLICT (game_id, language_code) DO NOTHING;
