INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Towers Eternity', 'Call in sick and unplug the phone! The third installment of the award-winning Mahjong series lets you choose from three different play modes, create tile sets and backdrops, make layouts to share, and chat with players using in-game messaging. The enthralling fun of Mahjong is something that everyone in the family can enjoy!' FROM games WHERE igdb_id = 16179 ON CONFLICT (game_id, language_code) DO NOTHING;
