INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi Yuugi Genbu Kaiden Gaiden: Kagami no Miko', 'Fushigi Yuugi Genbu Kaiden: Kagami no Miko is a simulation game for Playstation 2, based on the shoo manga Fushigi Yuugi Genbu Kaiden. It was ported to PSP on September 21, 2006. It is the first game of the Fushigi Yuugi series, and it takes place in the original Fushigi Yuugi Genbu Kaiden manga.' FROM games WHERE igdb_id = 62179 ON CONFLICT (game_id, language_code) DO NOTHING;
