INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bible Game', 'A trivia game to test gamers'' biblical knowledge, The Bible Game for Game Boy Advance combines action/adventure play style with trivia challenges. In their quest to protect the Armor of God, players may choose to play as either Billy or Jenny across seven levels including forest, snowy tundra, desert, and tropical island environments. Along the way they must answer questions from both the Old and New Testaments. Either the New International Version or King James translation may be selected, and three levels of difficulty keep the game accessible for all ages.' FROM games WHERE igdb_id = 5746 ON CONFLICT (game_id, language_code) DO NOTHING;
