INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaga Arrangement', 'The 2005 release Namco Museum Battle Collection included another game titled Galaga Arrangement. However, it was not the same game. This title was re-released on Xbox 360 in Namco Museum: Virtual Arcade. It was than re-released on the iPhone under the name Galaga Remix. It featured new bosses and weapons, as well as the original Galaga.' FROM games WHERE igdb_id = 178409 ON CONFLICT (game_id, language_code) DO NOTHING;
