INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach: Erabareshi Tamashi', 'The player can chose any two main characters from the Bleach series to start with. However, the player can only choose from five characters at the start of the game. As the player progress, more characters become available. The player is given missions requiring them to fight against hollows in different parts of Karakura Town and members of the Gotei 13 in Soul Society.' FROM games WHERE igdb_id = 43533 ON CONFLICT (game_id, language_code) DO NOTHING;
