INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game ni Nattayo! Dokuro-chan: Kenkou Shindan Daisakusen', 'Game ni Nattayo! Dokuro-chan: Kenkou Shindan Daisakusen is an adventure game for PlayStation 2, released on 2005. The game revolves around conversation, with various mini-games along the way. They play mini-games with cherry blossoms, and the results affect the girls'' likeability. And once you''ve cleared the minigame, you can watch bonus CGs of the heroine you''ve chosen as your game partner.' FROM games WHERE igdb_id = 248390 ON CONFLICT (game_id, language_code) DO NOTHING;
