INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ryudragon', 'You are in charge of a small Japanese fiefdom. Your goal is to compete for the position of supremacy in feudal Japan, represented by the figure of the Shogun. To achieve this feat, you must know how to manage your fief, your workers, and your army, and fight together with your clan, in this contest that will involve a lot of strategy to achieve victory...' FROM games WHERE igdb_id = 296188 ON CONFLICT (game_id, language_code) DO NOTHING;
