INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Columbine Massacre RPG!', 'Super Columbine Massacre RPG! is a role-playing video game created by Danny Ledonne and released in April 2005. The game recreates the 1999 Columbine High School shootings near Littleton, Colorado. Players assume the roles of gunmen Eric Harris and Dylan Klebold and act out the massacre, with flashbacks relating parts of Harris and Klebold''s past experiences. The game begins on the day of the shootings and follows Harris and Klebold after their suicides to fictional adventures in perdition.' FROM games WHERE igdb_id = 134526 ON CONFLICT (game_id, language_code) DO NOTHING;
