INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('50-cent-bulletproof', 4011, '2005-11-17', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3hbo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fhv5rezqfndu2wa3zvef.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '50 Cent: Bulletproof', 'Take on the role of 50 Cent as he gets caught in a web of corruption, double-crosses and shady deals that lead him on a bloody path through New York''s drug underworld. Working with the unlikeliest of allies, the streets heat up as 50 takes on the most dangerous crime families in the city, uncovering an international conspiracy with devastating implications. Intended exclusively for mature players, this unapologetically violent game features the monetarily monikered rapper in its starring role, as a streetwise tough seeking revenge against a mysterious gang of thugs that filled him with lead and left him for dead. The hero can gain access to a variety of firearms and other weapons, and can learn more than 25 deadly reversal moves. In the third-person shooter style of the popular 128-bit generation Grand Theft Auto games, players follow a series of missions that lead them through the game''s storyline. Bulletproof features previously unreleased music and video by 50 Cent, and the game allows players to set up their own music and video play lists of this included material. The voices and likenesses of other famous musicians portray supporting characters, including Lloyd Banks (lock pick), Tony Yayo (demolitions expert), and Young Buck (weapon specialist) as members of 50''s G-Unit posse, Eminem as the "shady" Detective McVicar, and rap music luminary Dr. Dre as the wizened back-alley arms dealer Grizz.' FROM games WHERE igdb_id = 4011 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 4011 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
