INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting For One Piece', 'Fighting For One Piece is a fighting game for the Playstation 2 console inspired by the successful One Piece anime. The game is different from many other One Piece games which used chibi versions of the characters, like One Piece Grand Adventure, instead the characters are modelled after their anime counterparts. It was released on September 6, 2005.' FROM games WHERE igdb_id = 65911 ON CONFLICT (game_id, language_code) DO NOTHING;
