INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom II', 'Doom II was included in Doom 3 Collector''s Edition for the Xbox, which was released in 2005. This port includes an exclusive level, "Betray". It featured multiplayer like the PC version, however not through Xbox Live. This port was programmed by Vicarious Visions. The Xbox version of Doom 3: Resurrection of Evil also contains this same port, as well as Master Levels for Doom II.' FROM games WHERE igdb_id = 260018 ON CONFLICT (game_id, language_code) DO NOTHING;
