INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1955: The Secret Mission', '1955 - The Secret Mission is a top down shooter. The player is the last remaining allied pilot and is given a secret mission to destroy "The Iron Cannon". As the game is java based the graphics are not advanced. There are various enemies to engage including multiple bosses. Powerups and extra lives can be found within the game and there are two levels of difficulty.' FROM games WHERE igdb_id = 80075 ON CONFLICT (game_id, language_code) DO NOTHING;
