INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('airborne-troops-countdown-to-d-day', 27451, '2005-01-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8cpw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsr25.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airborne Troops: Countdown to D-Day', 'It''s 48 hours before the D-day invasion of Normandy. You are John Welsh, an elite paratrooper dropped behind enemy lines to complete missions crucial to the success of the invasion. You must avoid detection, organize the resistance fighters, and destroy key targets relying only on your wits and elite training. You must succeed at all costs. Failure is not an option. And so begins Airborne Troops, where stealth, intelligence, courage, and deadly aim win the day. Explore historically authentic locations, while using realistic weapons as you draw on your skills with knives, pistols, rifles, machine guns, and even panzerschrecks to dispatch your enemies in almost a dozen levels of World War II destruction.' FROM games WHERE igdb_id = 27451 ON CONFLICT (game_id, language_code) DO NOTHING;
