INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Outdoor Adventures', 'Join Mama, Papa, Ichigo, and Ringo as they explore as a family on a tropical island. Take the Hunting & Fishing expedition of a lifetime with 22 adventures across North America and beyond. Stalk monster bucks and trophy big game or stop off and fish the local waters. Experience the sights and sounds of a true-to-life outdoor adventure where stealth, strategy and technique are of the utmost importance!' FROM games WHERE igdb_id = 3844 ON CONFLICT (game_id, language_code) DO NOTHING;
