INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fired Up', 'Fired Up is a vehicular combat game available on the PlayStation Portable which supports up to eight players. The game features a demo of Wipeout Pure. The game features three places and five playable drivers. Fired up features game sharing and downloadable levels. It is an advancement on the 2003 PlayStation 2 game Hardware: Online Arena.' FROM games WHERE igdb_id = 22451 ON CONFLICT (game_id, language_code) DO NOTHING;
