INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortyr II', 'Mortyr II is set during World War II and follows British intelligence officer Sven Mortyr, who is sent to his Nordic homeland to investigate rumours of a Nazi super-weapon. Sven is horrified to find his own father has been forced to work on the unit, and must thus use all his covert skills to infiltrate the Nazi stronghold and prevent the completion of the weapon and rescue his father.' FROM games WHERE igdb_id = 8343 ON CONFLICT (game_id, language_code) DO NOTHING;
