INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galzoo Island', 'Leo is called a genius in using basic magic spells. But he is still learning the spells for monster capturing and he can''t even tame weak monsters yet.One day he meets with a monster girl ''Captain Vanilla'' and she teleports him to a mysterious island saying this will help him master his magic.' FROM games WHERE igdb_id = 185286 ON CONFLICT (game_id, language_code) DO NOTHING;
