INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piano Wizard', 'Allegro Rainbow''s Piano Wizard is the music learning video game that painlessly teaches anyone to play the piano. It gives every player instant success and joy, because they will immediately be able to play their favorite songs! The game''s patented sound and color learning cues transform tedious and repetitive practice sessions into an exciting and rewarding video game experience for people of all ages and musical abilities.' FROM games WHERE igdb_id = 129960 ON CONFLICT (game_id, language_code) DO NOTHING;
