INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frank the Farmhand Part 2', 'After having escaped from the agents, Frank and his friends are captured by the american military and brought to a military camp on the island of Guija. In the second part of Frank''s adventures you''ll find yourself on an exotic island with lots of new characters to interact with, and many challenging problems to solve. This game is bigger, better and more beautiful than its predecessor!' FROM games WHERE igdb_id = 169517 ON CONFLICT (game_id, language_code) DO NOTHING;
