INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Movies', 'Behind every box office hit and Hollywood star is a movie mogul who makes it happen. In The Movies, that mogul is you. Create your own studio from the ground up. Direct your own movies and call the shots on budgets, actors, locations and more. From script to screen, will your films be smash hits or break the bank? It''s all up to you, baby.' FROM games WHERE igdb_id = 2995 ON CONFLICT (game_id, language_code) DO NOTHING;
