INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hi-5 DVD Game', 'Hi-5 DVD Game is a DVD game released by Universal Studios Home Entertainment. This interactive DVD game comes with a set of coloured picture mats that are used to play ten games all presented by and featuring the original Hi-5 members. The winners of each game will be crowned a Hi-5 Action Hero by each of the Hi-5 members, from their respective games.' FROM games WHERE igdb_id = 274991 ON CONFLICT (game_id, language_code) DO NOTHING;
