INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guncom 2', 'Prepare yourselves for a whole host of horrific hordes that are just waiting to fill you with fear.  No matter what other-worldy essence fills their souls though, there’s one thing they have in common; they will all bow to your Death Crimson gun!  Keep your nerve through cobbled backstreets, abandoned mansions, deserted factories and more in an attempt to get to the bottom of the vast, ever present waves of undead foes.  Experience the ultimate in lightgun blasting action by inviting a friend along for 2-player co-operative missions!' FROM games WHERE igdb_id = 43532 ON CONFLICT (game_id, language_code) DO NOTHING;
