INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance 86.4 Funky Radio Station', 'DANCE 86.4 FUNKY RADIO STATION is part of the BEMANI line of arcade music video games. Like the DanceDanceRevolution series, it''s a dance simulation game, although it''s aimed at younger players. The title is read as "DANCE Yaroyo", which means "Let''s DANCE". DANCE 86.4 has only three foot panels, which are lined up horizontally, and it supports up to two players.' FROM games WHERE igdb_id = 314336 ON CONFLICT (game_id, language_code) DO NOTHING;
