INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tails Sky Adventure', 'Tails Sky Adventure is an LCD game created for distribution at McDonald''s restaurants. They were offered as a part of Happy Meals for a limited time in 2005. This is one of the games that wasn''t included in the US promotion. The object of the game is to shoot down enemies which come along using the turret on Tails plane, the Tornado. If 15 are destroyed the level will advance by one. If 5 ships pass by the player the game will end.' FROM games WHERE igdb_id = 198601 ON CONFLICT (game_id, language_code) DO NOTHING;
