INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikkyou Pawafuru Puroyakyu 12', 'Jikkyō Powerful Pro Yakyū 12 is the 12th installment in the series of baseball games by Konami. It features a tournament mode with 12 real professional teams and 15 high school teams, exhibition mode (for one or two players) and the series trademark Success mode, where players create a player character and train him to become a professional baseball player.' FROM games WHERE igdb_id = 124494 ON CONFLICT (game_id, language_code) DO NOTHING;
