INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('night-watch', 20540, '2005-08-18', 47, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsokj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Watch', 'Based on the most successful Russian-made movie ever, the Night Watch game asks players to take part in a millennia-old struggle of supernatural forces; a conflict of which ordinary humans are either completely oblivious, or in which they are unwittingly being used as pawns. In the Night Watch universe, there are people among us who appear ordinary, but who are different; they call themselves "Others." These Others can channel magical power as devastating attacks and defenses. Those who support the forces of light are known as the Night Watch, while those that fight on the side of darkness are the Day Watch. These two sides have been locked in an epic battle with the common hope of one ultimately claiming a decisive victory and a right to rule the world.' FROM games WHERE igdb_id = 20540 ON CONFLICT (game_id, language_code) DO NOTHING;
