INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunting Ground', 'The story follows Fiona Belli, a young girl who the player must guide through Belli Castle and its immediate environments in an effort to escape. Along the way, players must solve puzzles, unlock doors and evade, hide or attempt to fight against the castle''s inhabitants. Fiona is accompanied by Hewie, a White Shepherd and the two must work as a team to solve certain puzzles and outwit their pursuers.' FROM games WHERE igdb_id = 14605 ON CONFLICT (game_id, language_code) DO NOTHING;
