INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('talkman', 23141, '2005-12-16', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rjh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsu11.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TalkMan', 'Thanks to TalkMan - and a large blue multilingual bird called Max PSP (PlayStationPortable) is on a mission to break the ice and tear down those barriers that keep nationalities apart. Bring the art of language to your gestures, put words behind the shrugs, turn Spanglish into perfecto Espanol, make the move on the girl or guy in that foreign bar who catches your eye - in short, become a jetsetter able to communicate in six languages with more than 3000 crucial phrases at your fingertips. Following the recent success of the Asian version in Japan and Korea, Talkman is coming to Europe and Australasia this spring on PSP, courtesy of Sony Computer Entertainment Europe. TalkMan is the portable language entertainment tool and interactive phrasebook that makes sure you are ready to talk - wherever you are and comes packed with the phrases that count in six languages: French; English; German; Spanish; Italian and, of course, Japanese' FROM games WHERE igdb_id = 23141 ON CONFLICT (game_id, language_code) DO NOTHING;
