INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aladdin Pinball', 'Aladdin Pinball is a high-speed game set in the magical land of Agrabah. Players join their favorite characters from the film, Aladdin and Princess Jasmine, for pinball fun on three exciting boards. Players can experience the excitement of the city marketplace as they knock down scimitars or hit pots and watermelons. They can also enter the Cave of Wonders and aim for the magic lamp to unlock the multi-ball feature for bonus points, or move into the Royal Palace to knock down Jafar and save Princess Jasmine.' FROM games WHERE igdb_id = 127641 ON CONFLICT (game_id, language_code) DO NOTHING;
