INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oppai Slider 2', 'In Oppai Slider 2, the player can choose between three different scenarios, each starring a girl in a different role: a nurse (with the player as a doctor), a maid (whose master is the player), and a "sailor", who is simply a girl the player has to teach how to swim. It is actually the same girl, named Asakura Koyori, in three different stories.' FROM games WHERE igdb_id = 22425 ON CONFLICT (game_id, language_code) DO NOTHING;
