INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MS Saga: A New Dawn', 'MS Saga is a console-style role-playing adventure, featuring an original storyline, setting, and characters, along with fan-familiar "mobile suit" ''mechs from the G Gundam, Gundam Wing, and Mobile Suit Gundam series. Most battles are fought using mobile suits, and the game allows extensive customization of them, encouraging players to collect and use more powerful parts. The story takes place on a world emerging in the aftermath of a great war. Inhabitants must harness the power of their former enemies, but danger comes as this power begins to slip into the wrong hands.' FROM games WHERE igdb_id = 20492 ON CONFLICT (game_id, language_code) DO NOTHING;
