INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bratz: Rock Angelz', 'You get the chance to live the life of a Rock Angel as you help Cloe, Jade, Sasha and Yasmin start their own fashion magazine. The search for the perfect scoop will take you around the globe, where famous places and famous people make for amazing adventures. Shop for the latest fashions! Explore Bratz town and Bratz City! Start your very own fashion magazine!' FROM games WHERE igdb_id = 3836 ON CONFLICT (game_id, language_code) DO NOTHING;
