INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clubhouse-games', 18597, '2005-11-03', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ac8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqvxu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clubhouse Games', 'It''s game night and everyone''s invited. Play more than 20 classic board, card and party games alone, with friends or via Nintendo Wi-Fi Connection. With familiar favorites like checkers, darts and poker, Clubhouse Games is for everyone and part of the Touch Generations library. Video game newcomers will appreciate the easy-to-use interface. Players can challenge up to seven friends with one game card via Multi-Card Play or DS Download Play. Can''t play checkers without shouting "KING ME!" across the table? The in-game (PictoChat-like) feature takes table talk to a new level. There''s no need to lug around cards or boards when you want to play a quick game. Clubhouse Games is one-stop gaming that will appeal to everyone''s tastes, whether they''re in the mood for bowling, backgammon, bridge or billiards.' FROM games WHERE igdb_id = 18597 ON CONFLICT (game_id, language_code) DO NOTHING;
