INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winx Club', 'Join the Winx Club and prepare for an interactive adventure of fairies, fantasy, fashion and magic! Take on the role of Bloom, a 16 year-old Earth girl, who discovers she is a magical fairy! Meet Bloom''s fairy friends, Stella, Flora, Tecna and Musa and battle with them against the evil witches in this most exciting girls adventure ever! Featuring a wide range of community-based activities and collectibles, The Winx Club will whisk you away on an unforgettable adventure!' FROM games WHERE igdb_id = 200907 ON CONFLICT (game_id, language_code) DO NOTHING;
