INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX World Tour', 'This game features Motocross racing and showcases popular motorsports commentator, Jamie Little. Race against 11 other riders on 32 different tracks around the globe. This game features Supercross (indoor), Motocross (outdoor), and Supermoto (dirt and asphalt) tracks. Splitscreen multiplayer for 2-4 players is also available. Jamie Little, in addition to providing race commentary, is also a playable character.' FROM games WHERE igdb_id = 43636 ON CONFLICT (game_id, language_code) DO NOTHING;
