INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Championship Manager', 'Eidos, one of the world''s leading publishers and developers of entertainment software, announces a Sony PSP version of Championship Manager. Developed by Gusto Games, Championship Manager PSP is a fully portable version of the best known football management simulation, and also boasts a wealth of new features. Dealing with everything from transfers to training, tactics to tabloids, championship Manager is the closest you''ll get to real-life football.' FROM games WHERE igdb_id = 269426 ON CONFLICT (game_id, language_code) DO NOTHING;
