INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Core: Last Raven', 'Two powerful groups, the Alliance and the Vertex, are fighting for world dominance and victory hinges upon the "Raven" pilots. You are a Raven, an elite mech warrior who must choose sides between the fighting powers. Ravens face the ultimate decision in the fight for survival, either to fiercely defend their chosen side or fight alone and face the wrath of all Ravens.' FROM games WHERE igdb_id = 19410 ON CONFLICT (game_id, language_code) DO NOTHING;
