INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Paddle', 'Based on a famous comics series. Kid Paddle is a young gamer, and everything in his life spins around videogames. Help Kid win the Virtua3000, the latest virtual game console! Train for the tournament through 26 mini games. Play with Kid, Horace, Big Bang and the little Barbarian. Beat high scores, win clues for an online prize on Kid''s website.' FROM games WHERE igdb_id = 49476 ON CONFLICT (game_id, language_code) DO NOTHING;
