INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannon', 'Shooting game exclusive to the Mega Drive (Genesis). You can play alone against the console or challenge a friend in a two-player game. Press the A, B or C button once to set the aim of the gun, then again to set the force and shoot a bullet. The arrow in the center of the screen indicates the direction and intensity of the wind, be careful as this may change the trajectory of the ball. If you are lucky, you may not have the wind to fear.' FROM games WHERE igdb_id = 210539 ON CONFLICT (game_id, language_code) DO NOTHING;
