INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RPG Maker 3', 'This game is the sixth numbered entry, and the second one for the PlayStation 2, of the role-playing game construction kit. Assemble your own custom 3D RPG using a tile-based map editor, set events, quests, and story elements, and make it all come together in a coherent, enjoyable game. Select from thousands of different character graphics and magic effects, sound samples, and more.' FROM games WHERE igdb_id = 24144 ON CONFLICT (game_id, language_code) DO NOTHING;
