INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cheese Quest 3D: The Brother Lady Saga', 'Cheesequest features Cheese playing a game in his head. It begins with Cheese saying he likes games and sticking a video game cartridge into his mouth. He then goes into his imagination, avoiding obstacles, completing a monkey dance lesson, getting a horsey, fighting a boss (cake), getting a "Water Horsey (a shark that Cheese rides)", and avoiding falling cereal. After he avoids the cereal, he says "I like- CEREAL!" and he takes the video game out of his mouth.' FROM games WHERE igdb_id = 234896 ON CONFLICT (game_id, language_code) DO NOTHING;
