INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stronghold-2', 9460, '2005-04-18', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nr5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bjcqdqcuyikzy3sqd5hj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold 2', 'Tax, torture or treat your peasants! Rehabilitate criminals or sentence them to death? Decide as you joust over a lavish banquet, all while under siege from the warmongering Lord Barclay. Will you entertain with medieval tournaments or rule with an iron fist and dispense feudal justice to overworked and malnourished peasants? With powerful barons jostling for power over a disintegrating kingdom, it is up to you to stem the tides of ambition and unite the land under the one true King! Building on the sim gameplay of the original Stronghold, Stronghold 2 allows players to rule as they please and still conquer each skirmish. Unhappy peasants turn to crime and must be punished, rival lords can raise entire armies on their title alone and sieges must be fought tooth and nail, with close combat taking place inside castle structures. Stronghold 2 Online extends this gameplay to competitive multiplayer for up to eight players, with offline skirmish mode also available against computer-controller opponents. The online services used GameSpy which was shutdown. The Steam Edition is the only version of Stronghold 2 that still features multiplayer using Steam Multiplayer.' FROM games WHERE igdb_id = 9460 ON CONFLICT (game_id, language_code) DO NOTHING;
