INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aim for the Top! Gunbuster', 'A Japanese only PlayStation 2 adventure game which follows the story of the classic Gainax 1988 anime OVA. Top o Nerae! GunBuster is a video game released in Japan for the Playstation 2 on February 3, 2005. The game does not follow the events of the series, but instead tells a new story which builds on the themes of the original. The game is divided into roaming adventure scenes in which Noriko must converse with characters and collect items to advance the story, and action segments in which Noriko and Kazumi pilot the Gunbuster mecha.' FROM games WHERE igdb_id = 57987 ON CONFLICT (game_id, language_code) DO NOTHING;
