INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunstar Super Heroes', 'Blue and Red, the lead characters in Gunstar Super Heroes, must once again keep a stone of great power from falling into the hands of an evil empire intent on resurrecting the God of Ruin. Blue and Red take on the same adventure using different paths, effectively making for two unique play-through experiences. Players will tackle six wildly inventive levels and take on gigantic bosses that fill the entire Game Boy Advance screen.' FROM games WHERE igdb_id = 6422 ON CONFLICT (game_id, language_code) DO NOTHING;
