INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrome: SpecForce', 'Chrome: SpecForce is a standalone expansion pack for Chrome. The gameplay in Chrome: SpecForce is largely identical to that of Chrome, although it has been streamlined, while the overall difficulty has also been lowered. The player can survive significantly more damage (ostensibly due to wearing Power Armor), healing and ammo items are more common-place, and the control scheme has been condensed so as to require fewer separate commands.' FROM games WHERE igdb_id = 16147 ON CONFLICT (game_id, language_code) DO NOTHING;
