INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal Championship 2: The Liandri Conflict', 'Unreal Championship 2: The Liandri Conflict enhances both single and multiplayer gameplay, including all-new player acrobatics, third-person camera mode, vehicles, and intense melee abilities. In the single player campaign, you''ll fight your way through new cities and arenas as Anubis, who attempts to retake his people''s Nakhti Rite of Ascension Tournament from the machinations of the Liandri Corporation. The game also offer players the chance to fight head-to-head in eight-player tournaments over Xbox Live or System Link as any one of 14 characters--each with new adrenaline powers that enable offensive and defensive combos.' FROM games WHERE igdb_id = 6221 ON CONFLICT (game_id, language_code) DO NOTHING;
