INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-bibleman-videogame-adventure-a-fight-for-faith', 206659, '2005-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hcm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmhw3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bibleman Videogame Adventure: A Fight for Faith', 'Now is your chance to help the greatest heroes of all time! Join Bibleman and the Bible Adventure Team in this highly engaging interactive adventure! Based on the best-selling Bibleman videos and national live-tour, A Fight for Faith, players can choose to be Bibleman, Cypher or Biblegirl. Featuring 9 levels of action, adventure and challenging puzzles, video and sounds from the Bibleman video, as well as original music by the Rock n'' Roll Worship Circus, players must take on the Wacky Protester and his henchmen in order to save the children of Andersonville, using the Biblical scripture and the Full Armor of God.' FROM games WHERE igdb_id = 206659 ON CONFLICT (game_id, language_code) DO NOTHING;
