INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starshine Legacy Episode 3: Legend of Pandoria', 'Anne is a young girl with big dreams - she wants to become a model and a successful dressage rider. What seems like the opportunity of a lifetime arises when a famous perfume company comes to her school scouting for their next model. little does she know that this is the beginning of an adventure that will take her and her trusted horse Concorde into another world. The time has come for Anne and Concorde to overcome their fears and face their destiny in the Starshine Legacy.' FROM games WHERE igdb_id = 196738 ON CONFLICT (game_id, language_code) DO NOTHING;
