INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sticky Balls', 'Sticky Balls is an action puzzle game published by Gizmondo Studios and developed in Manchester and designed by John and Ste Pickford. Sticky Balls uses a pool-like interface where the player utilizes a spring-loaded rod to shoot brightly colored balls at each other. Bouncing the balls against the table walls doubles the score of the shot but hitting a ball of a different color, or failing to hit anything causes the player to lose a turn.' FROM games WHERE igdb_id = 94905 ON CONFLICT (game_id, language_code) DO NOTHING;
