INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ratchet-deadlocked', 1790, '2005-10-25', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oyo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xigs2c03iksezuag1rwa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet: Deadlocked', 'Ratchet: Deadlocked is the fourth game in the Ratchet & Clank series by Insomniac Games. Deadlocked is different in its counterparts in that it focuses more on shooting than platforming and puzzle elements. The game allows you to use two bots to fight along side you, which can be upgraded over time with better weapons and firepower. There are 10 total weapons in the game, significantly less than the other games. However, modding these weapons is more emphasized than before, with different kinds of Alpha and Omega mods. Omega mods can be used on any weapon, and range from the freeze mod to the magma mod. Alpha mods are weapon-specific, and increase the rate of fire, ammo capacity, and power. The game also features online multiplayer. Clank is not a playable character in this game, although he gives advice to Ratchet over his communication link.' FROM games WHERE igdb_id = 1790 ON CONFLICT (game_id, language_code) DO NOTHING;
