INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman', 'The Bomberman series returns with Bomberman for Nintendo DS, boasting the first eight-player wireless LAN action for the Nintendo DS system and supporting the DS microphone. Bomberman''s addictive blend of strategy and action will keep puzzle fans and players of all ages and skill levels drawn to the 100 stages of gameplay.' FROM games WHERE igdb_id = 22287 ON CONFLICT (game_id, language_code) DO NOTHING;
