INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire: Darkstalkers Collection', 'This compilation features the original arcade versions of the games, as well as hidden arranged versions of the three Vampire Savior games, which introduce a corrupt dhampir version of Donovan, Dee, as a secret playable character with his own storyline.' FROM games WHERE igdb_id = 20012 ON CONFLICT (game_id, language_code) DO NOTHING;
