INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major League Baseball 2K5', 'Not enhanced, not adjusted, not tweaked, and not updated. Major League Baseball 2K5 is all new and sets the standard for baseball video games. Dominate the diamond with innovative pitching and batting controls, all-new Maximum Fielding and On Command baserunning featuring active picture-in-picture display, quick select controls, and a plethora of slide options. Indulge in the true MLB atmosphere as a brand-new graphics engine brings stadiums, player models, animations, weather effects, and cut-scenes to life in breathtaking detail. With an exclusive ESPN presentation system featuring expert commentary from Jon Miller, Joe Morgan, and Karl Ravech in-studio, Major League Baseball 2K5 is your ticket to the Big Leagues.' FROM games WHERE igdb_id = 8907 ON CONFLICT (game_id, language_code) DO NOTHING;
