INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perfect Ace 2: The Championships', 'Following on from the success of Perfect Ace: Pro Tournament Tennis, which sold 80,000 units across Europe last summer, Oxygen Interactive have announced they are to launch a sequel title Perfect Ace 2: The Championships in time for the Wimbledon Championships. Featuring new stadiums, new player models, full player editor, new game mechanics and new animations, Perfect Ace 2: The Championships offers the finest Tennis simulation yet. Perfect Ace 2 takes you on a complete World tour for singles, Doubles and mixed Doubles as well as the option of a quick match anywhere in the world, inc multi-player options for up to 4 players.' FROM games WHERE igdb_id = 43247 ON CONFLICT (game_id, language_code) DO NOTHING;
