INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jade Empire: Limited Edition', 'Jade Empire is a martial arts action RPG, that delivers a stunning visual and gameplay experience. The Limited Edition of Jade Empire adds a new default playable character, monk Zeng, with the exclusive Monk Spade fighting style. It also contains a bonus disc with a Making of Jade Empire video and demo versions of Forza Motorsport, Conker Live & Reloaded, and MechAssault 2: Lone Wolf.' FROM games WHERE igdb_id = 47318 ON CONFLICT (game_id, language_code) DO NOTHING;
