INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-western', 43665, '2005-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ozo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar58h3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Western', 'Samurai Gojiro Kiryuu comes to the American West in search of his brother. His journey takes him to a corrupt town ruled by a sinister land baron named Goldberg. Though Gojiro isn''t interested in righting wrongs, he is soon caught up in the town''s problems: killing highway robbers, protecting a woman from would-be rapists, and thwarting Goldberg''s machinations. Focused on destroying Gojiro, Goldberg unleashes an endless stream of minions... all fodder for Gojiro''s blade. But Goldberg has an ace up his sleeve... Samurai Western is a third-person action game. Gojiro''s blade is more than a match for Old West weaponry as he can ably deflect or sidestep bullets. As Gojiro completes levels, he upgrades his skills, unlocks new swords and stances, and adds Western accessories to his wardrobe. Primarily a single-player game, Samurai Western has a two player co-op mode and unlockable characters for both modes.' FROM games WHERE igdb_id = 43665 ON CONFLICT (game_id, language_code) DO NOTHING;
