INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('doraslot-bakuenchi-kyojin-no-hoshi-ii', 269492, '2005-07-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9978.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DoraSlot: Bakuenchi! Kyojin no Hoshi II', 'Dora-Slot: Kyojin no Hoshi II, is a Pachislot game based on real machines. The theme of the game is based on Japanese manga/anime series Star of the Giants. The main game consists of 3 different variants of the slot machines, which feature two side bars that interact based on how you score and if you activate any bonuses or meet certain conditions. These feature characters from the series, with voice acting and Japanese humor. The library allows users to play with the sounds and music, view a catalog about the machine, or even view the staging for various transitions without playing through the game repeatedly. Although, it''s still up to luck if you''ll complete it, you can hear the voice acting and see the effects that the machine uses in this mode. Pachislot games are a cross between pachinko machines and western style slot machines. They play more like western style machines, although they often feature mechanical enhancements, animations, mini-games, and various ways of getting bonuses that are more complex than other some other machines.' FROM games WHERE igdb_id = 269492 ON CONFLICT (game_id, language_code) DO NOTHING;
