INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Luigi: Partners in Time', 'The famous Mario Brothers return in this sequel to the humorous Superstar Saga. In this adventure, Princess Peach takes a trip in a time machine, but when it returns, there''s only a monster inside! The heroic brothers travel back in time only to discover that evil alien life forms known as the Shroobs have taken over the Mushroom Kingdom, and no-one is safe! They soon meet up with their younger selves, and set out to stop the alien menace, not to mention rescue the Princess!' FROM games WHERE igdb_id = 3364 ON CONFLICT (game_id, language_code) DO NOTHING;
