INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/d4i6hkjjvw25hsffjxqz.jpg', 9, false FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
INSERT INTO game_artwork (game_id, url, artwork_type, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q0l.jpg', 'promotional', 0, true FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=e_XUDY9SjI4', 'https://img.youtube.com/vi/e_XUDY9SjI4/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=sxd3cNV9WlE', 'https://img.youtube.com/vi/sxd3cNV9WlE/maxresdefault.jpg', 'Trailer', 'trailer', 1, false FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 98 AND rs.code = 'PEGI' AND r.code = '3' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 98 AND rs.code = 'ESRB' AND r.code = 'E' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', true, true, true FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'de', 'German', true, true, true FROM games WHERE igdb_id = 98 ON CONFLICT DO NOTHING;
